void add_to_draw_list_once(P<void> bone) {
    s32 count;
    P<s32> entry;
    s32 object;
    u32 i;

    count = GAME_VAR(draw_list_count);
    object = M2C_FIELD(bone, P<s32> , 0x14);
    i = 0;
    if (count != 0) {
        entry = (P<s32> )field::var::frame_draw_list;
        for (;;) {
            i += 1;
            if (*entry != object) {
                entry += 4;
                if (i >= (u32) count) {
                    count = GAME_VAR(draw_list_count);
                    GAME_TABLE(frame_draw_list, (count * 4)) = object;
                    GAME_VAR(draw_list_count) = (s16) (count + 1);
                    return;
                }
                continue;
            }
            break;
        }
    } else {
        GAME_TABLE(frame_draw_list, (count * 4)) = object;
        GAME_VAR(draw_list_count) = (s16) (count + 1);
    }
}

