// Erases the whole Flash (osFlashAllErase) and writes a fresh header (0x80062CA8: generation 0, +4 = 1, the value 0x80721, two 8-byte strings from 0x80043630 / 0x80043638, kind 0x4000 at +2) to the first page that takes it (write_flash_page). Returns 0, or -1 / the erase's error. Callers open_flash_save, create_new_save. (2026-11-12, names3: confirmed from the lifted C++: osFlashAllErase, then the header words 0x80062CB0 = 0, +4 = 1, 0x80062CC0 = 0x80721, the two 8-byte strings into +8 / +0x18, +0x20 = 0, kind 0x80062CAA = 0x4000, and the page loop.)
// From the N64 function at 0x80004CE4 (61 instructions).
// Called by: open_flash_save, create_new_save.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 format_flash_save(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x18, ctx->r31);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x10, ctx->r16);
    s32 os_flash_all_erase_result;
    s32 os_flash_all_erase_result_2;
    s32 result;
    s32 write_failed;
    u32 j;
    u32 i;
    s32 header_byte;
    P<void> header_at;

    os_flash_all_erase_result = lift_call<s32>(ctx, ::osFlashAllErase_recomp)();
    os_flash_all_erase_result_2 = os_flash_all_erase_result;
    result = os_flash_all_erase_result_2;
    if (os_flash_all_erase_result_2 == 0) {
        i = 0;
        GAME_VAR(flash_header_generation) = 0;
        M2C_FIELD((P<void> )field::var::flash_header_generation, P<s32> , 4) = 1;
        GAME_VAR(flash_header_format_id) = 0x80721;
        do {
            header_at = i + field::var::flash_header_generation;
            M2C_FIELD(header_at, P<u8> , 8) = (u8) GAME_TABLE(flash_header_string_a, i);
            header_byte = GAME_TABLE(flash_header_string_b, i);
            i += 1;
            M2C_FIELD(header_at, P<u8> , 0x18) = header_byte;
        } while (i < 8U);
        j = 0;
        M2C_FIELD((P<void> )field::var::flash_header_generation, P<s16> , 0x20) = 0;
        GAME_VAR(flash_header_kind) = 0x4000;
        for (;;) {
            M2C_FIELD((P<void> )field::var::flash_header_generation, P<u16> , 0x14) = j;
            M2C_FIELD((P<void> )field::var::flash_header_generation, P<u16> , 0x16) = j;
            lift_call<s32>(ctx, n64::copy_memory)(field::var::flash_header_last_page, field::var::flash_write_buffer, 0x80);
            write_failed = lift_call<s32>(ctx, n64::write_flash_page)((s32) (s16) j);
            if (write_failed != 0) {
                j += 1;
                if (j < 0x3FEU) {
                    continue;
                }
            } else {
                write_failed = 1;
            }
            break;
        }
        result = write_failed;
    }
    return result;
}

// Fills the save image (*0x80062C20) from the Flash: returns 1 for a blank save (header generation 0 and +0xC = 1), else reads every block from its newest page (the map 0x80062FF0, block count at header +0x28, as commit_save_to_flash keeps it), last first, the last one cut to the image size's remainder (read_save_block_from_flash). Returns -1 on failure or no image, else the last read's result. Caller open_save_image.
// From the N64 function at 0x80004DD8 (68 instructions).
// Called by: open_save_image.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 33 comparisons, no difference (caller twin v11, 0.84, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, select_wcw, smoke_singles; see the header's caller-twin note).
s32 load_save_from_flash(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x28);
    frame.keep(0x20, ctx->r31);
    frame.keep(0x1C, ctx->r19);
    frame.keep(0x18, ctx->r18);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x10, ctx->r16);
    s32 block_minus_1_2;
    s32 var_a1;
    s32 result;
    u32 block_minus_1;
    u32 block;
    u32 temp_a0;
    u32 temp_v1;
    u32 flash_save_size_mod_120;
    u32 var_a2;

    var_a1 = -1;
    if (GAME_VAR(flash_save_image) != 0) {
        if ((GAME_VAR(flash_header_generation) == 0) && (GAME_VAR_AS(flash_header_write_count, s32) == 1)) {
            var_a1 = 1;
            result = var_a1;
            return result;
        }
        temp_v1 = GAME_VAR_AS(flash_save_size, u32);
        block = M2C_FIELD((P<void> )field::var::flash_header_generation, P<u16> , 0x20);
        temp_a0 = (u32) GAME_VAR_AS(flash_save_size, u32) / 120U;
        flash_save_size_mod_120 = (u32) GAME_VAR_AS(flash_save_size, u32) % 120;
        var_a2 = flash_save_size_mod_120;
        if ((flash_save_size_mod_120 << 0x10) == 0) {
            var_a2 = 0x78;
        }
        result = -1;
        if ((s32) (block << 0x10) > 0) {
            for (;;) {
                block_minus_1 = block - 1;
                block = block_minus_1;
                block_minus_1_2 = (s32) (s16) block_minus_1;
                var_a1 = (s32) (s16) lift_call<s32>(ctx, n64::read_save_block_from_flash)((s32) GAME_ARRAY(flash_block_map, (block_minus_1_2 * 2)), block_minus_1_2, (s32) (s16) var_a2);
                if (var_a1 != -1) {
                    var_a2 = 0x78;
                    if (block_minus_1_2 > 0) {
                        continue;
                    }
                }
                break;
            }
            result = var_a1;
        }
    } else {
        result = var_a1;
    }
    return result;
}

// Whether the Game Boy cartridge read by gb_pak_read_id is the one the game talks to: the 11-byte title at 0x8006330C (id + 0x34) equals the string at 0x80043650 and the company code (id + 0x44) is '78' (0x3738, the same company as the Controller Pak note). Returns 1 or 0. Only caller open_transfer_pak.
// From the N64 function at 0x80004FE0 (21 instructions).
// Called by: open_transfer_pak.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 gb_cart_is_ours(void) {
    s32 i;
    s32 result;

    i = 0;
    for (;;) {
        if (GAME_TABLE(transfer_pak_cart_title, i) == GAME_TABLE(gb_cart_expected_title, i)) {
            i += 1;
            if (i < 0xB) {
                continue;
            }
        }
        break;
    }
    result = 0;
    if (i == 0xB) {
        result = GAME_VAR(transfer_pak_cart_company) == 0x3738;
    }
    return result;
}

// Opens the Transfer Pak on `channel`: takes the SI lock (take_shared_lock, kept at 0x8004365C), gb_pak_init on the pfs 0x80063270, gb_pak_read_id (id 0x800632D8, status 0x8006332C), checks the cartridge is the game's partner (gb_cart_is_ours) and the connector (gb_pak_check_connector (func_80039430), taken to be osGbpakCheckConnector). Returns 0 when ready, 4 for another cartridge, bit 0 on an error (result in 0x80063328); the lock is given back when the init fails. Callers read_gb_cart_ram, write_gb_cart_ram.
// From the N64 function at 0x80005034 (62 instructions).
// Has gotos where m2c couldn't find the loop or the if: its structure is to be tidied by hand.
// Called by: read_gb_cart_ram, write_gb_cart_ram.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 open_transfer_pak(recomp_context* ctx, s32 channel) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x1C, ctx->r31);
    frame.keep(0x18, ctx->r18);
    s32 queue;
    s32 gb_pak_init;
    s32 gb_pak_read_id;
    s32 result;
    s32 result_now;

    result = 0;
    if (GAME_VAR(transfer_pak_lock) == 0) {
        GAME_VAR(transfer_pak_lock) = lift_call<s32>(ctx, n64::take_shared_lock)();
    }
    queue = GAME_VAR(transfer_pak_lock);
    gb_pak_init = lift_call<s32>(ctx, n64::gb_pak_init)(queue, field::var::transfer_pak_pfs, channel);
    GAME_VAR(transfer_pak_result) = gb_pak_init;
    if (gb_pak_init == 0) {
        gb_pak_read_id = lift_call<s32>(ctx, n64::gb_pak_read_id)(field::var::transfer_pak_pfs, field::var::transfer_pak_cart_id, field::var::transfer_pak_status);
        GAME_VAR(transfer_pak_result) = gb_pak_read_id;
        if (gb_pak_read_id == 0) {
            if (lift_call<s32>(ctx, n64::gb_cart_is_ours)() != 1) {
                result = 4;
            } else {
                GAME_VAR(transfer_pak_result) = lift_call<s32>(ctx, n64::gb_pak_check_connector)(field::var::transfer_pak_pfs, field::var::transfer_pak_status);
            }
            goto block_9;
        }
        result_now = result | 1;
        return result_now;
    }
    lift_call<s32>(ctx, n64::release_shared_lock)();
    GAME_VAR(transfer_pak_lock) = 0;
block_9:
    result_now = result;
    if (GAME_VAR(transfer_pak_result) != 0) {
        result_now = result | 1;
    }
    return result_now;
}

// When the Transfer Pak is open (0x8004365C), turns its cartridge off (gb_pak_power(pfs, 0)) and gives back the SI lock (release_shared_lock). Callers read_gb_cart_ram, write_gb_cart_ram.
// From the N64 function at 0x8000512C (16 instructions).
// Called by: read_gb_cart_ram, write_gb_cart_ram.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void close_transfer_pak(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r31);
    if (GAME_VAR(transfer_pak_lock) != 0) {
        lift_call<s32>(ctx, n64::gb_pak_power)(field::var::transfer_pak_pfs, 0);
        lift_call<s32>(ctx, n64::release_shared_lock)();
        GAME_VAR(transfer_pak_lock) = 0;
    }
}

// Whether `address` and `size` are both multiples of 32, the address not negative and address + size at most 0xBFFF (the end of a Game Boy cartridge's RAM window, 0xA000-0xBFFF). Callers read_gb_cart_ram, write_gb_cart_ram.
// From the N64 function at 0x8000516C (15 instructions).
// Called by: read_gb_cart_ram, write_gb_cart_ram.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 gb_ram_range_ok(u32 address, s32 size) {
    s32 result;

    result = 0;
    if (!(address & 0x1F)) {
        result = 0;
        if (!(size & 0x1F)) {
            result = ((address >> 0x1F) | ((s32) (address + size) > 0xBFFF)) ^ 1;
        }
    }
    return result;
}

// Prepares the Game Boy cartridge's RAM through the Transfer Pak: writes 0 to 0x4000 (RAM bank 0) and, when that works, 0x0A to 0x0000 (the cartridge's RAM enable), 32-byte writes from 0x80063330 (gb_pak_read_write). Returns the last result. Callers read_gb_cart_ram, write_gb_cart_ram.
