// Called by: read_gb_cart_ram, write_gb_cart_ram.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void enable_gb_cart_ram(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x28);
    frame.keep(0x18, ctx->r16);
    frame.keep(0x24, ctx->r31);
    frame.keep(0x20, ctx->r18);
    frame.keep(0x1C, ctx->r17);
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    lift_call<s32>(ctx, n64::zero_bytes)(field::var::gb_cart_ram_command, 0x20);
    GAME_VAR(gb_pak_write_last_byte) = 0;
    if (lift_call<s32>(ctx, n64::gb_pak_read_write)(field::var::transfer_pak_pfs, 1, 0x4000, field::var::gb_cart_ram_command, 0x20) == 0) {
        lift_call<s32>(ctx, n64::zero_bytes)(field::var::gb_cart_ram_command, 0x20);
        lift_out_v0 = 0xA;
        GAME_VAR(gb_pak_write_last_byte) = 0xA;
        lift_call<s32>(ctx, n64::gb_pak_read_write)(field::var::transfer_pak_pfs, 1, 0, field::var::gb_cart_ram_command, 0x20);
    }
}

// Reads `size` bytes of the Game Boy cartridge's memory at `address` into `buffer` through the Transfer Pak on `channel` (0-3): gb_ram_range_ok (else 0x80), open_transfer_pak, enable_gb_cart_ram, gb_pak_read_write(read), gb_pak_get_status (bit 0 clear: 0x10), close_transfer_pak. Returns 0 or error bits (8 a pak error). Caller read_gb_save.
