    s32 var_v1;

    var_f12 = x;
    double_80055830 = GAME_VAR(f64_1);
    var_v1 = 0;
    if (double_80055830 < (f64) var_f12) {
        var_v1 = 1;
        var_f12 = 1.0f / var_f12;
    }
    double_80055838 = GAME_VAR(f64_minus_1);
    if ((f64) var_f12 < double_80055838) {
        var_v1 = -1;
        var_f12 = 1.0f / var_f12;
    }
    var_f0_2 = 8.0f;
    var_v0 = 8;
    var_f6 = 0.0f;
    do {
        temp_f4_2 = var_f0_2 * var_f0_2 * var_f12 * var_f12;
        temp_f2_2 = (2.0f * var_f0_2) + 1.0f + var_f6;
        var_v0 -= 1;
        var_f0_2 = (f32) ((f64) var_f0_2 - double_80055830);
        var_f6 = temp_f4_2 / temp_f2_2;
    } while (var_v0 > 0);
