    s32 character_index;
    s32 character_index_offset;
    s32 i;
    P<u8> destination_at;
    P<u8> text_at;

    destination_at = destination;
    text_at = text;
    i = 0;
    max_chars_low_byte = max_chars & 0xFF;
    if (max_chars_low_byte > 0) {
        for (;;) {
            character_index = lift_call<s32>(ctx, n64::character_index)((s32) *text_at);
            character_index_offset = character_index * 2;
            M2C_FIELD(destination_at, P<u8> , 0) = GAME_ARRAY_AS(wide_character_table, character_index_offset, u8);
            text_at += 1;
            M2C_FIELD(destination_at, P<u8> , 1) = (u8) GAME_ARRAY_AS(wide_character_second_bytes, character_index_offset, u8);
            destination_at += 2;
            if (*text_at != 0) {
                i += 1;
                if (i < max_chars_low_byte) {
                    continue;
                }
            }
            break;
        }
    }
    *destination_at = 0;
    return destination_at;
