// Has gotos where m2c couldn't find the loop or the if: its structure is to be tidied by hand.
// Called by: wide_character_entry.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 wide_character_index(P<void> c) {
    s32 result;
    P<u8> entry_at;
    s32 c_byte_1;

    entry_at = (P<u8> )field::var::wide_character_table;
    result = 0;
    c_byte_1 = M2C_FIELD(c, P<u8> , 1);
    for (;;) {
        if (c_byte_1 != M2C_FIELD(entry_at, P<u8> , 1)) {
            entry_at += 2;
            goto block_8;
        }
        if (M2C_FIELD(c, P<u8> , 0) != M2C_FIELD(entry_at, P<u8> , 0)) {
            entry_at += 2;
block_8:
            result += 2;
            if (*entry_at == 0) {
                return -1;
            }
            continue;
        }
        break;
    }
    return result;
}

// The address of the two-byte character `c`'s entry in the table at 0x80067C60 (wide_character_index), 0 when it isn't there. No converted callers. (2026-11-12, names4: confirmed from the lifted C++: the name says only what the code does).
// From the N64 function at 0x80008274 (13 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 wide_character_entry(recomp_context* ctx, s32 c) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r31);
    s32 wide_character_index;
    s32 wide_character_index_2;
    s32 result;

    wide_character_index = lift_call<s32>(ctx, n64::wide_character_index)(c);
    wide_character_index_2 = wide_character_index;
    result = 0;
    if (wide_character_index_2 >= 0) {
        result = wide_character_index_2 + field::var::wide_character_table;
    }
    return result;
}

// The game's bit packing: ORs the low `bits` bits of `value` into `buffer` at bit *`position` (bit 0 of the first byte up, little-endian across up to four bytes; the bits are expected clear), and moves *`position` on by `bits`. unpack_bits reads them back; mod/src/save.c reads the save with the same packing. (Roles confirmed 2026-11-12 from the code.)
// From the N64 function at 0x800082A8 (42 instructions).
// Called by: pack_rules, func_800E27F4, pack_costume_for_save, write_titles_to_save and 5 more.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 2448 comparisons, no difference (leaf twin, 0.84, modes_reg_rumble (match not reached), modes_regular_boot, select_wcw).
void pack_bits(s32 value, s32 bits, s32 buffer, P<s32> position) {
    s32 bit;
    s32 bit_rounded;
    s32 high_byte_bits;
    u32 shifted;
    P<void> byte;

    bit = *position;
    bit_rounded = bit;
    if (bit < 0) {
        bit_rounded = bit + 7;
    }
    shifted = (value & ((1 << (bits & 31)) - 1)) << ((bit & 7) & 31);
    byte = buffer + (bit_rounded >> 3);
    high_byte_bits = shifted & 0xFF00;
    if (shifted & 0xFF) {
        M2C_FIELD(byte, P<u8> , 0) = (u8) (M2C_FIELD(byte, P<u8> , 0) | shifted);
        high_byte_bits = shifted & 0xFF00;
    }
    if (high_byte_bits != 0) {
        M2C_FIELD(byte, P<u8> , 1) = (u8) (M2C_FIELD(byte, P<u8> , 1) | (shifted >> 8));
    }
    if (shifted & 0xFF0000) {
        M2C_FIELD(byte, P<u8> , 2) = (u8) (M2C_FIELD(byte, P<u8> , 2) | (shifted >> 0x10));
    }
    if (shifted & 0xFF000000) {
        M2C_FIELD(byte, P<u8> , 3) = (u8) (M2C_FIELD(byte, P<u8> , 3) | (shifted >> 0x18));
    }
    *position += bits;
}

// The game's bit unpacking, the reverse of pack_bits: returns the `bits`-bit value at bit *`position` of `buffer` (bit 0 of the first byte up, read from the four bytes there) and moves *`position` on by `bits` (mod/src/save.c reads the save the same way). (Roles confirmed 2026-11-12 from the code.)
// From the N64 function at 0x80008350 (27 instructions).
// Called by: unpack_rules, unpack_saved_superstar, load_titles_from_save, unpack_story_records and 5 more.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 16148 comparisons, no difference (leaf twin, 0.84, match_tag, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, rules_single_hardcore, select_wcw, smoke_singles).
s32 unpack_bits(s32 bits, s32 buffer, P<s32> position) {
    s32 bit;
    s32 bit_rounded;
    s32 byte_byte_1;
    s32 byte_byte_2;
    s32 byte_byte_3;
    s32 byte_byte_0;
    P<void> byte;

    bit = *position;
    bit_rounded = bit;
    if (bit < 0) {
        bit_rounded = bit + 7;
    }
    byte = buffer + (bit_rounded >> 3);
    byte_byte_0 = M2C_FIELD(byte, P<u8> , 0);
    byte_byte_1 = M2C_FIELD(byte, P<u8> , 1);
    byte_byte_2 = M2C_FIELD(byte, P<u8> , 2);
    byte_byte_3 = M2C_FIELD(byte, P<u8> , 3);
    *position = bit + bits;
    return ((u32) (byte_byte_0 | (byte_byte_1 << 8) | (byte_byte_2 << 0x10) | (byte_byte_3 << 0x18)) >> ((bit & 7) & 31)) & ((1 << (bits & 31)) - 1);
}

