    s32 unused;
    s32 block;
    s32 style_low_half;
    s32 style_size_bits_2;
    s32 style_low_half_2;
    s32 record;
    s32 temp_v0_2;
    s32 text_texture_total;
    s32 text_texture;
    s32 work;
    s32 size;
    s32 result;
    s32 style_size_bits;

    style_low_half = style & 0xFFFF;
    text_texture_entry = lift_call<s32>(ctx, n64::find_text_texture_entry)(text, style_low_half);
    record = text_texture_entry;
    result = 0;
