s32 find_superstar_record(s32 id, s32 costume) {
    s32 index;
    P<u16> entry_at;

    index = 0;
    entry_at = (P<u16> )field::var::entrant_ids;
    for (;;) {
        if (*entry_at != id) {
            index += 1;
            goto block_8;
        }
        if (GAME_TABLE(entrant_costumes, index) != costume) {
            index += 1;
block_8:
            entry_at += 2;
            if (index >= 0x65) {
                return 0;
            }
            continue;
        }
        break;
    }
    return index;
}

