    P<u16> temp_v0_2;
    P<u16> temp_v1;
    P<u8> var_s0;
    u32 temp_a0_2;
    P<void> temp_s1;

    unused = lift_call<s32>(ctx, n64::zero_bytes)(*(P<s32> )0x80104D28, 0x6D8);
    unused_2 = lift_call<s32>(ctx, n64::zero_bytes)(*(P<s32> )0x80106520, 0x37);
