// Looks Superstar `id`'s ordinal (func_8000AE78) up in the 0-ended list of (ordinal, value) byte pairs at 0x800477E4 and returns value + 1, 0 when absent. The ROM's list is empty (its first pair is 0, 0), so it returns 0 unless something fills it. Callers superstar_exists, count_paired_superstars.
// From the N64 function at 0x8000AF08 (24 instructions).
// Called by: superstar_exists, count_paired_superstars.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 paired_ordinal_value(recomp_context* ctx, s32 id) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r31);
    s32 ordinal;
    P<u8> entry_at_2;
    P<u8> entry_at;
    u32 listed_ordinal;

    ordinal = lift_call<s32>(ctx, n64::superstar_to_ordinal)(id);
    if (GAME_VAR(paired_ordinal_list) != 0) {
        entry_at = (P<u8> )field::var::paired_ordinal_list;
        entry_at_2 = (P<u8> )field::var::paired_ordinal_list_values;
        listed_ordinal = GAME_VAR(paired_ordinal_list);
        for (;;) {
            entry_at += 2;
            if (ordinal == listed_ordinal) {
                return *entry_at_2 + 1;
            }
            listed_ordinal = *entry_at;
            entry_at_2 += 2;
            if (listed_ordinal == 0) {
                break;
            }
        }
    }
    return 0;
}

