    i = 0;
    GAME_VAR(edit_movesets) = movesets_block;
    unused = lift_call<s32>(ctx, n64::zero_bytes)(address, 0x15F0);
    lift_call<s32>(ctx, n64::zero_bytes)(GAME_VAR(edit_movesets), 0xF30);
    lift_call<s32>(ctx, n64::load_roster_files)();
