// Gives back a file from acquire_shared_file by its data `data`: its users count down, and at 0 the node is unlinked from *0x80047EB4 and the data and node freed. Caller release_part_shared_picture.
// From the N64 function at 0x8000BDF0 (39 instructions).
// Called by: release_part_shared_picture.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 514 comparisons, no difference (caller twin v11, 0.84, match_tag, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, select_wcw, smoke_singles; see the header's caller-twin note).
void release_shared_file(recomp_context* ctx, s32 data) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x14, ctx->r31);
    P<M2C_UNK> shared_file;
    P<M2C_UNK> previous_file;
    s32 block;
    u32 users_minus_1;

    shared_file = GAME_VAR_AS(shared_files, P<M2C_UNK>);
    previous_file = NULL;
    if (shared_file != NULL) {
        for (;;) {
            if (SHARED_FILE_AS(shared_file, data, s32) != data) {
                previous_file = shared_file;
                shared_file = SHARED_FILE_AS(shared_file, next, P<M2C_UNK>);
                if (shared_file != NULL) {
                    continue;
                }
            }
            break;
        }
        if (shared_file != NULL) {
            users_minus_1 = SHARED_FILE_AS(shared_file, users, u16) - 1;
            SHARED_FILE_AS(shared_file, users, u16) = users_minus_1;
            if (!(users_minus_1 & 0xFFFF)) {
                if (previous_file == NULL) {
                    GAME_VAR_AS(shared_files, P<M2C_UNK>) = (P<M2C_UNK> ) SHARED_FILE_AS(shared_file, next, P<M2C_UNK>);
                } else {
                    *previous_file = SHARED_FILE_AS(shared_file, next, P<M2C_UNK>);
                }
                block = SHARED_FILE_AS(shared_file, data, s32);
                lift_call<s32>(ctx, n64::heap_free)(block);
                SHARED_FILE_AS(shared_file, data, s32) = 0;
                lift_call<s32>(ctx, n64::heap_free)((s32) shared_file);
            }
        }
    }
}

// Walks the shared file list (*0x80047EB4) to its end and does nothing with it; presumably a debug count left empty. No converted callers.
// From the N64 function at 0x8000BE8C (9 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void walk_shared_files(void) {
    P<M2C_UNK> shared_file;

    shared_file = GAME_VAR_AS(shared_files, P<M2C_UNK>);
    if (shared_file != NULL) {
        do {
            shared_file = *shared_file;
        } while (shared_file != NULL);
    }
}

