    s32 scale;
    P<s8> record_at;
    s32 record;
    s32 point_byte;
    u32 record_at_half_0;
    u32 point_count;
    u32 i;
    s32 mesh_byte_7;
    s32 mesh_byte_0;
    s32 mesh_byte_5;
    s32 mesh_byte_1;
    s32 mesh_byte_4;
    s32 mesh_byte_6;
