    P<void> record_at_3;

    record_at = mesh + 8;
    mesh_byte_7 = M2C_FIELD(mesh, P<u8> , 7);
    vertices_at = vertices;
    i = 0;
    mesh_byte_1 = M2C_FIELD(mesh, P<u8> , 1);
    mesh_byte_0 = M2C_FIELD(mesh, P<u8> , 0);
    point_count = mesh_byte_1 & ~0x80;
    mesh_byte_4 = M2C_FIELD(mesh, P<u8> , 4);
    scale = (mesh_byte_0 & ~0x80) + 1;
    mesh_byte_5 = M2C_FIELD(mesh, P<u8> , 5);
    mesh_byte_6 = M2C_FIELD(mesh, P<u8> , 6);
