// Frees what a model part has on the heap, the bone's draw object excepted (mod/src/announce.c: what the model has on the heap). Only when the part is loaded (`part` +0 not 0; then cleared): heap_free's the bone's display list (`bone` +0x10) and give_bone_draw_object(bone, 0) clears the object's mesh; then the part's buffers: +0x10 (when set, +0x10 .. +0x1C are all just cleared after it), else +0x14, +0x18, +0x1C (freed only when +0x30 is 0, a part that shares them leaving them), then +0x20 and +0x24, each cleared. (2026-11-12: the arguments' roles read from the code -- fields.json's Bone has +0x10 the display list.)
// From the N64 function at 0x8000D3F8 (71 instructions).
// Has gotos where m2c couldn't find the loop or the if: its structure is to be tidied by hand.
// Called by: free_model_slot, free_slot_extra_parts, free_arena_models, rebuild_ring_arena_in_place and 8 more.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 1093 comparisons, no difference (caller twin v11, 0.84, match_tag, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, rules_single_hardcore, select_wcw, smoke_singles; see the header's caller-twin note).
void free_part_meshes(recomp_context* ctx, P<void> bone, P<void> part) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x18, ctx->r31);
    frame.keep(0x14, ctx->r17);
    s32 display_list;
    s32 part_block;
    s32 part_points;
    s32 part_commands;
    s32 part_triangle_commands;
    s32 part_picture;
    s32 part_palette;
    s32 unused;

    if (MODEL_PART(part, loaded) != 0) {
        MODEL_PART(part, loaded) = 0U;
        display_list = BONE(bone, display_list);
        if (display_list != 0) {
            lift_call<s32>(ctx, n64::heap_free)(display_list);
            BONE(bone, display_list) = 0;
        }
        unused = lift_call<s32>(ctx, n64::give_bone_draw_object)((s32) bone, 0);
        part_block = MODEL_PART(part, block);
        if (part_block != 0) {
            lift_call<s32>(ctx, n64::heap_free)(part_block);
            MODEL_PART(part, block) = 0;
            MODEL_PART(part, points) = 0;
            MODEL_PART(part, commands) = 0;
            goto block_16;
        }
        part_points = MODEL_PART(part, points);
        if (part_points != 0) {
            if (MODEL_PART(part, pool) == 0) {
                lift_call<s32>(ctx, n64::heap_free)(part_points);
            }
            MODEL_PART(part, points) = 0;
        }
        part_commands = MODEL_PART(part, commands);
        if (part_commands != 0) {
            if (MODEL_PART(part, pool) == 0) {
                lift_call<s32>(ctx, n64::heap_free)(part_commands);
            }
            MODEL_PART(part, commands) = 0;
        }
        part_triangle_commands = MODEL_PART(part, triangle_commands);
        if (part_triangle_commands != 0) {
            if (MODEL_PART(part, pool) == 0) {
                lift_call<s32>(ctx, n64::heap_free)(part_triangle_commands);
            }
block_16:
            MODEL_PART(part, triangle_commands) = 0;
        }
        part_picture = MODEL_PART(part, picture);
        if (part_picture != 0) {
            lift_call<s32>(ctx, n64::heap_free)(part_picture);
            MODEL_PART(part, picture) = 0;
        }
        part_palette = MODEL_PART(part, palette);
        if (part_palette != 0) {
            lift_call<s32>(ctx, n64::heap_free)(part_palette);
            MODEL_PART(part, palette) = 0;
        }
    }
}

