    GAME_VAR(mesh_header_point_count) = (u8) (GAME_VAR(mesh_header_point_count) & 0x7F);
    POSE_MESH(entry, loaded) = 1;
    POSE_MESH_AS(entry, point_count, u8) = (u8) GAME_VAR(mesh_header_point_count);
    new_triangle_count = GAME_VAR(mesh_header_triangle_count);
    point_count = (s8) POSE_MESH(entry, point_count);
    POSE_MESH(entry, pool) = pool;
    POSE_MESH_AS(entry, triangle_count, u8) = new_triangle_count;
    if (point_count > 0) {
        POSE_MESH(entry, points) = lift_call<s32>(ctx, n64::alloc_pool_points)(pool, point_count & 0xFFFF);
    }
    triangle_count = POSE_MESH_AS(entry, triangle_count, u8);
    triangle_count_2 = (s32) (s8) triangle_count;
