    sine_3 = lift_call<f32>(ctx, n64::sine)(angle_3);
    cosine_3 = lift_call<f32>(ctx, n64::cosine)(angle_3);
    cosine_4 = cosine_3;
    cosine_4_times_sine_2 = cosine_4 * sine_2;
    sine_3_times_sine_2 = sine_3 * sine_2;
    MTXF_AS(matrix, m03, s32) = 0;
    MTXF_AS(matrix, m13, s32) = 0;
    MTXF(matrix, m20) = sine_2;
    MTXF_AS(matrix, m23, s32) = 0;
    MTXF_AS(matrix, m30, s32) = 0;
    MTXF_AS(matrix, m31, s32) = 0;
    MTXF_AS(matrix, m32, s32) = 0;
    MTXF(matrix, m00) = cosine_4 * cosine_2;
    MTXF(matrix, m22) = (f32) (cosine_2 * cosine);
    MTXF(matrix, m10) = (f32) (-sine_3 * cosine_2);
    MTXF(matrix, m21) = (f32) (-cosine_2 * sine);
    MTXF(matrix, m33) = 1.0f;
    MTXF(matrix, m01) = (f32) ((sine_3 * cosine) + (cosine_4_times_sine_2 * sine));
