void transform_point_xz(P<void> matrix, f32 x, f32 y, f32 z, P<f32> out_x, P<f32> out_z) {
    *out_x = (MTXF(matrix, m00) * x) + (MTXF(matrix, m10) * y) + (MTXF(matrix, m20) * z) + MTXF(matrix, m30);
    *out_z = (MTXF(matrix, m02) * x) + (MTXF(matrix, m12) * y) + (MTXF(matrix, m22) * z) + MTXF(matrix, m32);
}

