    s32 handle;
    s32 mapped_x10000;

    handle = 0;
    if ((u32) ((sound - 0x401) & 0xFFFF) < 0x2CU) {
        mapped_x10000 = GAME_TABLE(menu_sound_map_base, ((s32) (sound << 0x10) >> 0xF)) << 0x10;
    } else {
        mapped_x10000 = sound << 0x10;
    }
    sound_id = mapped_x10000 >> 0x10;
