    LiftAbiOut lift_out_t0{ctx->r8};   // the context's t0, kept in step with the original's
    s32 lift_mh_80017650_a = 0, lift_mh_80017650_b = 0;   // the operands of the mult before the mfhi at 80017650, as it read them
    s32 sound;
