                    unused = lift_call<s32>(ctx, n64::set_sound_volume)(play_sound_result_3, volume);
                    half_800484f4 = (u16) GAME_VAR_AS(crowd_cue_handle_turn, u16);
                    half_800484f4_plus_1 = half_800484f4 + 1;
                    lift_mh_80017650_a = (s32) (s16) half_800484f4_plus_1;
