        GAME_TABLE(rumble_queue_on_frames, offset) = 0;
        GAME_TABLE(rumble_queue_off_frames, offset) = 0;
        GAME_TABLE(rumble_queue_countdown, offset) = 0;
        unused = lift_call<s32>(ctx, n64::stop_rumble)((s32) (s16) i);
