    unused = lift_call<s32>(ctx, n64::zero_bytes)(packed, 0x17);
    unused_2 = lift_call<s32>(ctx, n64::write_bits)((s32) &cursor, (s32) LOOKS(unpacked, body_type), 5);
    unused_3 = lift_call<s32>(ctx, n64::write_bits)((s32) &cursor, (s32) LOOKS(unpacked, skin), 3);
    unused_4 = lift_call<s32>(ctx, n64::write_bits)((s32) &cursor, (s32) LOOKS(unpacked, ring_attire), 7);
    unused_5 = lift_call<s32>(ctx, n64::write_bits)((s32) &cursor, (s32) LOOKS(unpacked, ring_attire_colour_1), 5);
    unused_6 = lift_call<s32>(ctx, n64::write_bits)((s32) &cursor, (s32) LOOKS(unpacked, ring_attire_colour_2), 5);
    unused_7 = lift_call<s32>(ctx, n64::write_bits)((s32) &cursor, (s32) LOOKS(unpacked, upper_body), 7);
    unused_8 = lift_call<s32>(ctx, n64::write_bits)((s32) &cursor, (s32) LOOKS(unpacked, upper_body_colour_1), 5);
    unused_9 = lift_call<s32>(ctx, n64::write_bits)((s32) &cursor, (s32) LOOKS(unpacked, upper_body_colour_2), 5);
