// For each point of part `part` (+0x14, count +2): its y (+2) set by band (under 191 -> 90, under 311 -> 200, under 421 -> 320, under 531 -> 430, else 540) plus `lift`, and its alpha byte (+0xF) to `alpha`. Five tiers of a stand raised together: taken to be the crowd jumping. Callers func_8001B548 (set-up), update_arena (every frame).
// From the N64 function at 0x8001AF80 (38 instructions). The name is a best guess from the code alone.
// Called by: build_ring_arena, update_arena, build_ring_arena_mod_copy.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 21 comparisons, no difference (leaf twin, 0.84, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, select_wcw).
void lift_crowd_rows(P<void> part, s32 alpha, s32 lift) {
    s32 y;
    s32 next_point;
    s32 points;
    s32 point;
    s32 point_count;
    P<void> record_at;

    point_count = MODEL_PART(part, point_count);
    points = MODEL_PART(part, points);
    point = 0;
    if (point_count > 0) {
        record_at = points + 0xF;
        do {
            y = VERTEX_VIA(record_at, a, y);
            if (y >= 0x213) {
                VERTEX_VIA(record_at, a, y) = (s16) (lift + 0x21C);
            } else if (y >= 0x1A5) {
                VERTEX_VIA(record_at, a, y) = (s16) (lift + 0x1AE);
            } else if (y >= 0x137) {
                VERTEX_VIA(record_at, a, y) = (s16) (lift + 0x140);
            } else if (y < 0xBF) {
                VERTEX_VIA(record_at, a, y) = (s16) (lift + 0x5A);
            } else {
                VERTEX_VIA(record_at, a, y) = (s16) (lift + 0xC8);
            }
            next_point = point + 1;
            point = next_point;
            VERTEX_VIA_AS(record_at, a, a, s8) = alpha;
            record_at += 0x10;
        } while ((s32) (s8) next_point < MODEL_PART(part, point_count));
    }
}

