    lift_call<f32>(ctx, n64::make_rotation_xyz)((s32) &rotation, __builtin_bit_cast(s32, lift_plain(GAME_VAR(ladder_legs_angle))), 0, 0);
    lift_call<s32>(ctx, n64::make_translation_matrix)(field::var::ladder_piece_a_matrix, 0, 0, 0x42FC0000);
    unused = lift_call<s32>(ctx, n64::gu_mtx_cat_f)((s32) &rotation, field::var::ladder_piece_a_matrix, field::var::ladder_piece_a_matrix);
    lift_call<f32>(ctx, n64::make_rotation_xyz)((s32) &rotation, __builtin_bit_cast(s32, lift_plain(-GAME_VAR(ladder_legs_angle))), 0, 0x43340000);
