// Returns the wave data (+0x7C) of the first channel playing sound `handle`, or 0. No converted callers.
// From the N64 function at 0x80027B6C (23 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 sound_wave_data(s32 handle) {
    s32 sound_channel_count;
    s32 i;
    P<void> sound_channel;

    if (handle == 0) {
        return 0;
    }
    sound_channel_count = GAME_VAR(sound_channel_count);
    sound_channel = GAME_VAR_AS(sound_channels, P<void>);
    i = 0;
    if (sound_channel_count > 0) {
        for (;;) {
            i += 1;
            if (SOUND_CHANNEL(sound_channel, handle) != handle) {
                sound_channel += 0x13C;
                if (i >= sound_channel_count) {
                    return 0;
                }
                continue;
            }
            break;
        }
        return SOUND_CHANNEL(sound_channel, wave_data);
    }
    return 0;
}

// Queues sound command 0 with `handle` (queue_sound_command): run_sound_command (confirmed) sets bit 0 of the flags of the channels playing that handle, and sound_player_tick (confirmed) steps a channel's clock and script only while that bit is clear, so the sound holds where it is; command 1 (queue_sound_start) clears the bit again, and start_song starts its channels with it set. No converted callers. (2026-11-13, names5: renamed from queue_sound_stop and confirmed from the lifted C++: command 0 holds the handle's channels (flags bit 0, which the player tests before stepping them), it does not stop them).
// From the N64 function at 0x80027BC8 (9 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void queue_sound_pause(recomp_context* ctx, s32 handle) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x18, ctx->r31);
    Ref<s8> command_kind(frame.at(0x10));
    Ref<s32> command_handle(frame.at(0x14));
    s32 unused;

    command_handle = handle;
    command_kind = 0;
    unused = lift_call<s32>(ctx, n64::queue_sound_command)((s32) &command_kind);
}

// Queues sound command 1 with `handle` (queue_sound_command; the 8-byte command {kind 1, handle}), taken to start what start_song set up. Callers play_song, play_song_from_mark (func_80027244). (2026-11-12, names3: confirmed from the lifted C++: the two words {1, handle} on the stack handed to queue_sound_command.)
// From the N64 function at 0x80027BEC (10 instructions).
// Called by: play_song, play_song_from_mark.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 19 comparisons, no difference (caller twin v11, 0.84, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, select_wcw; see the header's caller-twin note).
void queue_sound_start(recomp_context* ctx, s32 handle) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x18, ctx->r31);
    Ref<s8> sp10(frame.at(0x10));
    Ref<s32> sp14(frame.at(0x14));
    s32 unused;

    sp14 = handle;
    sp10 = 1;
    unused = lift_call<s32>(ctx, n64::queue_sound_command)((s32) &sp10);
}

// Queues sound command 2 with `preset`, remembering it at *0x8008D2B4; the command handler (run_sound_command, func_80027EB8) calls select_reverb_preset. No converted callers. (2026-11-12, names4: confirmed from the lifted C++: command 2 with the preset, kept at *0x8008D2B4).
// From the N64 function at 0x80027C14 (12 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void queue_reverb_change(recomp_context* ctx, s32 preset) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x18, ctx->r31);
    Ref<s8> command_kind(frame.at(0x10));
    Ref<s32> command_preset(frame.at(0x14));
    s32 unused;

    command_preset = preset;
    GAME_VAR(remembered_reverb_preset) = preset;
    command_kind = 2;
    unused = lift_call<s32>(ctx, n64::queue_sound_command)((s32) &command_kind);
}

// Sets *0x8008D2B0, which lets sound scripts change the reverb (script_select_reverb acts only when it is 1); turning it off (0) first queues the remembered preset *0x8008D2B4 back (sound command 2, queue_sound_command), and keeps the old setting when that fails. No converted callers. (2026-11-12, names4: confirmed from the lifted C++: the name says only what the code does).
// From the N64 function at 0x80027C44 (23 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void set_script_reverb_control(recomp_context* ctx, s32 enabled) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x18, ctx->r16);
    frame.keep(0x1C, ctx->r31);
    Ref<s8> command_kind(frame.at(0x10));
    Ref<s32> command_preset(frame.at(0x14));
    s32 remembered_reverb_preset;
    s32 queued;

    queued = 1;
    if (enabled == 0) {
        remembered_reverb_preset = GAME_VAR(remembered_reverb_preset);
        command_kind = 2;
        command_preset = remembered_reverb_preset;
        GAME_VAR(remembered_reverb_preset) = remembered_reverb_preset;
        queued = lift_call<s32>(ctx, n64::queue_sound_command)((s32) &command_kind);
    }
    if (queued != 0) {
        GAME_VAR(sound_script_reverb_allowed) = enabled;
    }
}

// Once (+0xC bit 0): turns sound effect bank `bank`'s offsets into pointers (+0x14, and each of its +0 entries' +0x18, 8 bytes apart), clears +0x10, and makes it the default bank for sounds (*0x8008D2B8, set_next_sound_bank's default) when there is none. Callers start_sound_system, init_sound_driver.
// From the N64 function at 0x80027CA0 (33 instructions).
// Called by: start_sound_system, init_sound_driver.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 2 comparisons, no difference (leaf twin, 0.84, modes_regular_boot).
void set_up_sound_effect_bank(P<void> bank) {
    s32 bank_word_0;
    s32 i;
    P<void> bank_word_14;
    P<void> bank_at;

    if (!(SOUND_EFFECT_BANK(bank, flags) & 1)) {
        if (GAME_VAR(default_sound_bank) == NULL) {
            GAME_VAR(default_sound_bank) = bank;
        }
        bank_word_14 = SOUND_EFFECT_BANK(bank, entries);
        bank_word_0 = SOUND_EFFECT_BANK(bank, entry_count);
        i = 0;
        SOUND_EFFECT_BANK(bank, flags) = 1;
        SOUND_EFFECT_BANK(bank, wave_data) = 0;
        SOUND_EFFECT_BANK(bank, entries) = (P<void> ) (bank + bank_word_14);
        if (bank_word_0 > 0) {
            bank_at = bank;
            do {
                M2C_FIELD(bank_at, P<P<void>> , 0x18) = (P<void> ) (bank + M2C_FIELD(bank_at, P<P<void>> , 0x18));
                i += 1;
                bank_at += 8;
            } while (i < SOUND_EFFECT_BANK(bank, entry_count));
        }
    }
}

