    s32 unused;
    s32 sound_command_write_plus_1;
    s32 word_8008d2d0;
    s32 word_8008d2cc;

    sound_command_write = GAME_VAR(sound_command_write);
    word_8008d2cc = GAME_VAR(sound_command_ring_size);
    sound_command_write_plus_1 = sound_command_write + 1;
    next_write = LIFT_REM(sound_command_write_plus_1, word_8008d2cc);
    LIFT_DIV_CHECK(sound_command_write_plus_1, word_8008d2cc);
