// Sound-script command 0x95: pushes a loop at depth +0xDB (then +1): its repeat count (the next byte, 0xFF for ever) at +0x120, the script position after it at +0xE0, and the level and bend tracks' state (+0x38 to +0xF0, +0x34 to +0x100, +0xBC to +0x124, +0x70 to +0x128, +0xA2 to +0x110, +0xA4 to +0x118). script_loop_end goes back to it.
// From the N64 function at 0x8002A174 (27 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 627 comparisons, no difference (caller twin v11, 0.84, match_tag, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, rules_single_hardcore, select_wcw, smoke_singles; see the header's caller-twin note).
void script_loop_start(recomp_context* ctx, P<void> channel, s32 script) {
    LiftAbiOut lift_out_a2{ctx->r6};   // the context's a2, kept in step with the original's
    LiftAbiOut lift_out_a3{ctx->r7};   // the context's a3, kept in step with the original's
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    s32 script_plus_1;
    s32 level_track_counter;
    s32 loop_depth;
    P<void> loop_start_at;
    P<void> loop_track_at;
    P<void> loop_count_at;

    loop_depth = SOUND_CHANNEL(channel, loop_depth);
    script_plus_1 = script + 1;
    lift_out_v0 = script_plus_1;
    loop_count_at = channel + loop_depth;
    lift_out_a3 = (s32) loop_count_at;
    loop_start_at = (loop_depth * 4) + channel;
    M2C_FIELD(loop_count_at, P<u8> , 0x120) = (s32) M2C_FIELD(script, P<u8> , 0);
    M2C_FIELD(loop_start_at, P<s32> , 0xE0) = script_plus_1;
    M2C_FIELD(loop_start_at, P<s32> , 0xF0) = (s32) SOUND_CHANNEL(channel, level_track);
    M2C_FIELD(loop_start_at, P<s32> , 0x100) = (s32) SOUND_CHANNEL(channel, bend_track);
    M2C_FIELD(loop_count_at, P<u8> , 0x124) = (u8) SOUND_CHANNEL(channel, level);
    M2C_FIELD(loop_start_at, P<f32> , 0x128) = (f32) SOUND_CHANNEL(channel, bend_value);
    level_track_counter = SOUND_CHANNEL(channel, level_track_counter);
    loop_track_at = (loop_depth * 2) + channel;
    lift_out_a2 = (s32) loop_track_at;
    M2C_FIELD(loop_track_at, P<u16> , 0x110) = level_track_counter;
    M2C_FIELD(loop_track_at, P<u16> , 0x118) = (u16) SOUND_CHANNEL(channel, bend_track_counter);
    SOUND_CHANNEL(channel, loop_depth) = (u8) (SOUND_CHANNEL(channel, loop_depth) + 1);
}

// Sound-script command 0x97, three bytes: the gate's on level +0xD8, on frames +0xCE and off frames +0xCF, which channel_gate_step switches between (a tremolo or stutter). 0x98 (script_gate_off) turns it off.
// From the N64 function at 0x8002A1E0 (10 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 2 comparisons, no difference (leaf twin, 0.84, menu_from_attract).
P<void> script_set_gate(P<void> channel, P<void> script) {
    P<void> script_plus_1;

    script_plus_1 = script + 1;
    SOUND_CHANNEL(channel, gate_on_level) = (u8) M2C_FIELD(script, P<u8> , 0);
    SOUND_CHANNEL(channel, gate_on_frames) = (u8) M2C_FIELD(script, P<u8> , 1);
    SOUND_CHANNEL(channel, gate_off_frames) = (u8) M2C_FIELD(script_plus_1, P<u8> , 1);
    return script_plus_1 + 1 + 1;
}

