// Sound-script command 0x9E: reads an index (8 or 15 bits) and sets +0x84 to the song's (+0x74) drum map table +0x1C + index x 6; while +0x84 is set the interpreter looks each note up there (6 bytes per note: +0 instrument, +2 song envelope, +4 pan x 2, +5 the note played). 0x9F (script_drum_map_off) clears it.
// From the N64 function at 0x8002A268 (18 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void script_set_drum_map(recomp_context* ctx, P<void> channel, P<void> script) {
    LiftAbiOut lift_out_a2{ctx->r6};   // the context's a2, kept in step with the original's
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    s32 temp_a2_2;
    s32 temp_v0;
    s32 song;
    s32 new_drum_map;
    u32 var_a2;
    P<void> var_a1;

    var_a2 = M2C_FIELD(script, P<u8> , 0);
    lift_out_a2 = (s32) var_a2;
    temp_v0 = (s32) var_a2 < 0x80;
    var_a1 = script + 1;
    if (temp_v0 == 0) {
        temp_a2_2 = (s32) (var_a2 & 0x7F) << 8;
        var_a1 += 1;
        var_a2 = temp_a2_2 | (s32) M2C_FIELD(script, P<u8> , 1);
        lift_out_a2 = (s32) var_a2;
    }
    song = SOUND_CHANNEL(channel, song);
    new_drum_map = (s32) M2C_FIELD(song, P<s32> , 0x1C) + (var_a2 * 6);
    SOUND_CHANNEL(channel, drum_map) = new_drum_map;
    lift_out_v0 = (s32) var_a1;
}

