// Sound-script command 0xA1, three big-endian 16-bit offsets: continues the script at +0x80 (the script base) + the first, restarts the level track at +0x8C + the second (+0x38, +0xA2 = 1) and the bend track at +0x88 + the third (+0x34, +0xA4 = 1).
// From the N64 function at 0x8002A2C4 (28 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void script_jump_with_tracks(recomp_context* ctx, P<void> channel, P<void> script) {
    LiftAbiOut lift_out_a2{ctx->r6};   // the context's a2, kept in step with the original's
    LiftAbiOut lift_out_a3{ctx->r7};   // the context's a3, kept in step with the original's
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    s32 jump_offset;
    s32 bend_offset;
    s32 level_track_base;
    s32 new_level_track;
    s32 script_start;
    s32 bend_track_base;
    s32 low_byte;
    s32 script_byte_0;
    s32 script_plus_1_byte_1;
    s32 script_byte_1;
    s32 script_plus_plus_plus_1_byte_1;
    s32 script_plus_plus_1_byte_1;
    P<void> script_plus_1;
    P<void> script_plus_2;
    P<void> script_plus_3;

    script_byte_0 = M2C_FIELD(script, P<u8> , 0);
    script_plus_1 = script + 1;
    script_byte_1 = M2C_FIELD(script, P<u8> , 1);
    script_plus_2 = script_plus_1 + 1;
    script_plus_1_byte_1 = M2C_FIELD(script_plus_1, P<u8> , 1);
    script_plus_3 = script_plus_2 + 1;
    script_plus_plus_1_byte_1 = M2C_FIELD(script_plus_2, P<u8> , 1);
    level_track_base = SOUND_CHANNEL(channel, level_track_base);
    SOUND_CHANNEL_AS(channel, level_track_counter, s16) = 1;
    new_level_track = level_track_base + ((script_plus_1_byte_1 << 8) + script_plus_plus_1_byte_1);
    SOUND_CHANNEL(channel, level_track) = new_level_track;
    script_plus_plus_plus_1_byte_1 = M2C_FIELD(script_plus_3, P<u8> , 1);
    low_byte = M2C_FIELD((script_plus_3 + 1), P<u8> , 1);
    bend_track_base = SOUND_CHANNEL(channel, bend_track_base);
    jump_offset = (script_byte_0 << 8) + script_byte_1;
    lift_out_a2 = jump_offset;
    SOUND_CHANNEL_AS(channel, bend_track_counter, s16) = 1;
    script_start = SOUND_CHANNEL(channel, script_start);
    bend_offset = (script_plus_plus_plus_1_byte_1 << 8) + low_byte;
    lift_out_a3 = bend_offset;
    SOUND_CHANNEL(channel, bend_track) = (s32) (bend_track_base + bend_offset);
    lift_out_v0 = script_start + jump_offset;
}

