// Sound-script command 0xA3: the transpose +0xB9 = a random number below the first byte (sound_script_random (func_800293DC), the sound player's shift-register random number at *0x8008D2A4) plus the second.
// From the N64 function at 0x8002A344 (20 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 1009 comparisons, no difference (caller twin v11, 0.84, match_tag, menu_from_attract, rules_single_hardcore, smoke_singles; see the header's caller-twin note).
P<void> script_random_transpose(recomp_context* ctx, P<void> channel, P<void> script) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x18, ctx->r31);
    s32 sound_script_random;
    s32 sound_script_random_2;
    s32 range;

    range = M2C_FIELD(script, P<u8> , 0);
    sound_script_random = lift_call<s32>(ctx, n64::sound_script_random)((s32) range);
    sound_script_random_2 = sound_script_random;
    SOUND_CHANNEL(channel, transpose) = sound_script_random_2;
    SOUND_CHANNEL(channel, transpose) = (s8) (sound_script_random_2 + M2C_FIELD(script, P<u8> , 1));
    return script + 1 + 1;
}

