    new_w1 = lift_call<s32>(ctx, ::osVirtualToPhysical_recomp)(filter + 8);
    ACMD(commands, w1) = new_w1;
    ACMD_AT(commands, 1, w0) = (s32) ((AL_LOW_PASS(filter, first_byte) << 0x10) | (AL_LOW_PASS_AS(filter, gain, u16) | 0x0E000000));
