    frame.keep(0x3C, ctx->r23);
    frame.keep(0x40, ctx->r30);
    frame.keep(0x2C, ctx->r19);
    frame.keep(0x44, ctx->r31);
    frame.keep(0x38, ctx->r22);
    frame.keep(0x34, ctx->r21);
    frame.keep(0x30, ctx->r20);
    frame.keep(0x24, ctx->r17);
    frame.keep(0x20, ctx->r16);
