    LiftAbiOut lift_out_a1{ctx->r5};   // the context's a1, kept in step with the original's
    LiftAbiOut lift_out_a2{ctx->r6};   // the context's a2, kept in step with the original's
    LiftAbiOut lift_out_a3{ctx->r7};   // the context's a3, kept in step with the original's
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    Ref<s32> player(frame.at(0x18));
    Ref<s16> sp1C(frame.at(0x1C));
    s32 player_2;
    s32 player_3;
    s32 next_sample_time;
    s32 time_to_samples_no_round;
    s32 next_sample_time_2;
    s32 unused;
    s32 temp_ret_5;
    s32 al_globals_word_0;
    s32 temp_v0_12;
    s32 left_below_chunk;
    s32 temp_v0_16;
    s32 temp_v0_17;
    s32 next_sample_time_3;
    s32 loop_again;
    s32 al_globals_word_1c;
    s32 temp_v0_7;
    s32 microseconds;
    s32 next_sample_time_4;
    s32 al_globals_word_20;
    s32 player_word_10;
    s32 al_globals_word_20_2;
    s32 chunk;
    s32 left;
    s32 out;
    P<void> al_globals_word_38;
    P<void> al_globals;
    P<void> command_plus_8;
    P<void> command;

    al_globals = GAME_VAR_AS(al_globals, P<void>);
    left = samples;
    al_globals_word_0 = AL_SYNTH_AS(al_globals, clients, s32);
    lift_out_v0 = al_globals_word_0;
