// Scales the vector (x, y, z) in place to length 1. libultra's guNormalize.
// From the N64 function at 0x80038A60 (21 instructions).
// Called by: shade_bone_tree, gu_align_f, gu_rotate_f.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 1204780 comparisons, no difference (leaf twin, 0.84, match_tag, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, rules_single_hardcore, select_wcw, smoke_singles).
void gu_normalize(P<f32> x, P<f32> y, P<f32> z) {
    f32 inverse_length;
    f32 x_value;
    f32 y_value;
    f32 z_value;

    x_value = *x;
    y_value = *y;
    z_value = *z;
    inverse_length = 1.0f / sqrtf((z_value * z_value) + ((x_value * x_value) + (y_value * y_value)));
    *x = x_value * inverse_length;
    *y = y_value * inverse_length;
    *z = z_value * inverse_length;
}

// Fills a 4 by 4 float matrix that moves by x, y and z. They arrive as bit patterns in integer registers.
// From the N64 function at 0x80038AC0 (18 instructions).
// Called by: init_bone, func_80012BE0, restore_announce_table, build_closeup_scene and 5 more.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 3651 comparisons, no difference (leaf twin, 0.84, match_tag, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, rules_single_hardcore, select_wcw, smoke_singles).
void make_translation_matrix(P<void> matrix, s32 x, s32 y, s32 z) {
    MTXF_AS(matrix, m00, s32) = 0x3F800000;
    MTXF_AS(matrix, m01, s32) = 0;
    MTXF_AS(matrix, m02, s32) = 0;
    MTXF_AS(matrix, m03, s32) = 0;
    MTXF_AS(matrix, m10, s32) = 0;
    MTXF_AS(matrix, m11, s32) = 0x3F800000;
    MTXF_AS(matrix, m12, s32) = 0;
    MTXF_AS(matrix, m13, s32) = 0;
    MTXF_AS(matrix, m20, s32) = 0;
    MTXF_AS(matrix, m21, s32) = 0;
    MTXF_AS(matrix, m22, s32) = 0x3F800000;
    MTXF_AS(matrix, m23, s32) = 0;
    MTXF_AS(matrix, m30, s32) = x;
    MTXF_AS(matrix, m31, s32) = y;
    MTXF_AS(matrix, m32, s32) = z;
    MTXF_AS(matrix, m33, s32) = 0x3F800000;
}

// Puts the point (x, y, z) through `matrix` (4x4 floats, rows, translation in the last row) and writes the result to out_x, out_y, out_z. The port uses it for a bone's offset from its parent (exe arcade_bones.cpp).
// From the N64 function at 0x80038B20 (43 instructions).
// Called by: shade_bone_tree, compute_draw_object_depths, set_camera_view_rolled, animation_driver and 18 more.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 1786177 comparisons, no difference (leaf twin, 0.84, match_tag, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, rules_single_hardcore, select_wcw, smoke_singles).
void transform_point(P<void> matrix, f32 x, f32 y, f32 z, P<f32> out_x, P<f32> out_y, P<f32> out_z) {
    *out_x = (MTXF(matrix, m00) * x) + (MTXF(matrix, m10) * y) + (MTXF(matrix, m20) * z) + MTXF(matrix, m30);
    *out_y = (MTXF(matrix, m01) * x) + (MTXF(matrix, m11) * y) + (MTXF(matrix, m21) * z) + MTXF(matrix, m31);
    *out_z = (MTXF(matrix, m02) * x) + (MTXF(matrix, m12) * y) + (MTXF(matrix, m22) * z) + MTXF(matrix, m32);
}

