// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 sum_bytes(P<u8> bytes, s32 count) {
    s32 total;
    s32 done;
    P<u8> byte;

    byte = bytes;
    done = 0;
    total = 0;
    if (count > 0) {
        do {
            done += 1;
            total += *byte;
            byte += 1;
        } while (done < count);
    }
    return total & 0xFFFF;
}

