            level_rounded = level;
            if (effect_bits != 0x1000) {
                x_shifted = x << 0x10;
                goto block_14;
            }
            if (level < 0) {
                level_rounded = level + 3;
            }
            flags_low_half = flags & 0xFFFF;
            Ref<s32>(frame.at(0x10)) = 0x140 - (level_rounded >> 2);
            goto block_12;
