    if ((s32) total_seconds_mod_60 < 0xA) {
        M2C_FIELD(out_at_2, P<s8> , 0) = 0x30;
        out_at_2 += 1;
    }
    unused = lift_call<s32>(ctx, n64::copy_text_string)(lift_call<s32>(ctx, n64::format_number)(out_at_2, (s32) total_seconds_mod_60, 0), 0xF1A9);
