// From the N64 function at 0x800DD994 (84 instructions).
// Called by: date_text, make_field_text, update_keyboard_value, func_8013E764 and 1 more.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void format_date(recomp_context* ctx, s32 out, s32 date, s32 pad) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x18, ctx->r18);
    frame.keep(0x1C, ctx->r31);
    frame.keep(0x14, ctx->r17);
    s32 unused;
    s32 year_x16;
    s32 date_without_day;
    s32 date_div_32;
    s32 cursor;
    s32 cursor_2;
    s32 date_rounded_2;
    s32 rounded_date;
    s32 date_rounded;

    rounded_date = date;
    if (date < 0) {
        rounded_date = date + 0x1FF;
    }
    cursor = lift_call<s32>(ctx, n64::copy_string)(lift_call<s32>(ctx, n64::format_number)(out, ((s32) (rounded_date >> 9) % 100) + 0x79E, 0), field::var::date_separator_text);
    date_rounded = date;
    if (date < 0) {
        date_rounded = date + 0x1F;
    }
    date_div_32 = date_rounded >> 5;
    year_x16 = (rounded_date >> 9) * 0x10;
    if ((pad != 0) && (((s32) (date_div_32 - year_x16) / 10) == 0)) {
        M2C_FIELD(cursor, P<s8> , 0) = 0x20;
        cursor += 1;
    }
    cursor_2 = lift_call<s32>(ctx, n64::copy_string)(lift_call<s32>(ctx, n64::format_number)(cursor, date_div_32 - year_x16, 0), field::var::date_separator_text);
    date_rounded_2 = date;
    if (date < 0) {
        date_rounded_2 = date + 0x1F;
    }
    date_without_day = (date_rounded_2 >> 5) << 5;
    if ((pad != 0) && (((s32) (date - date_without_day) / 10) == 0)) {
        M2C_FIELD(cursor_2, P<s8> , 0) = 0x20;
        cursor_2 += 1;
    }
    unused = lift_call<s32>(ctx, n64::format_number)(cursor_2, date - date_without_day, 0);
}

