// Shows three of each player's HUD pieces again (clears 0x80 on the draw objects of the bones 0x8016BB70, 0x80175390, 0x80173090 + player x 0xDC); the counterpart of hide_player_huds. No caller found in the code.
// From the N64 function at 0x800DFDCC (27 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void show_player_hud_panels(recomp_context* ctx) {
    P<s32> temp_v1;
    P<s32> temp_v1_2;
    P<s32> temp_v1_3;
    s32 offset;
    u32 temp_gp;
    u32 i;

    temp_gp = ((s32)ctx->r28);
    i = 0;
    offset = 0;
    do {
        temp_v1 = GAME_TABLE(player_hud_panel_draw_objects, offset);
        *temp_v1 &= ~0x80;
        temp_v1_2 = GAME_TABLE(player_hud_name_plate_draw_objects, offset);
        *temp_v1_2 &= ~0x80;
        temp_v1_3 = GAME_TABLE(player_hud_spirit_bar_draw_objects, offset);
        i += 1;
        *temp_v1_3 &= ~0x80;
        offset += 0xDC;
    } while (i < temp_gp);
}

