// Slides the Royal Rumble countdown panel (two HUD quads 0x80157E48 / 0x80157D30 with their parts 0x80157F28 / 0x80157E10) each frame: when no countdown is up (0x80157F5C < 0, clear_rumble_countdown) its offset 0x80157F5D eases out to 0x6E and both are hidden there, else it eases back to 0; when the offset changes the quads are placed at x 0x172 + offset, y 0xBE / 0xBA (place_hud_quad_points). Caller update_match_hud.
// From the N64 function at 0x800E08C4 (82 instructions).
// Has gotos where m2c couldn't find the loop or the if: its structure is to be tidied by hand.
// Called by: update_match_hud.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 685 comparisons, no difference (caller twin v11, 0.84, match_tag, menu_from_attract, rules_single_hardcore, smoke_singles; see the header's caller-twin note).
void slide_rumble_countdown_panel(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x40);
    frame.keep(0x38, ctx->r31);
    Ref<s16> sp10(frame.at(0x10));
    Ref<u16> sp12(frame.at(0x12));
    Ref<s32> sp14(frame.at(0x14));
    Ref<f32> sp18(frame.at(0x18));
    Ref<f32> sp1C(frame.at(0x1C));
    Ref<f32> sp20(frame.at(0x20));
    Ref<s8> sp24(frame.at(0x24));
    Ref<s8> sp25(frame.at(0x25));
    Ref<s8> sp26(frame.at(0x26));
    Ref<s8> sp27(frame.at(0x27));
    f32 unused;
    P<s32> temp_a0_2;
    P<s32> temp_v1;
    s32 temp_v0;
    s32 temp_v1_2;
    s32 var_v0;
    s32 rumble_countdown_offset;
    s32 rumble_countdown_offset_2;
    s32 var_v0_2;
    u32 rumble_countdown_offset_u8;

    if (GAME_VAR(rumble_countdown_shown) < 0) {
        rumble_countdown_offset = GAME_VAR(rumble_countdown_offset);
        if (rumble_countdown_offset < 0x6E) {
            var_v0 = 0x6E - rumble_countdown_offset;
            if (var_v0 < 0) {
                var_v0 += 3;
            }
            var_v0_2 = rumble_countdown_offset + 1 + (var_v0 >> 2);
            goto block_8;
        }
        temp_v1 = GAME_VAR(rumble_countdown_number_object);
        *temp_v1 |= 0x80;
        temp_a0_2 = GAME_VAR(rumble_countdown_panel_object);
        temp_v0 = *temp_a0_2;
        GAME_VAR(rumble_countdown_offset) = 0x6E;
        *temp_a0_2 = temp_v0 | 0x80;
    } else {
        rumble_countdown_offset_u8 = (u8) GAME_VAR_AS(rumble_countdown_offset, u8);
        temp_v1_2 = rumble_countdown_offset_u8 << 0x18;
        if (temp_v1_2 > 0) {
            var_v0_2 = (rumble_countdown_offset_u8 + 1) - (temp_v1_2 >> 0x1A);
block_8:
            GAME_VAR(rumble_countdown_offset) = var_v0_2;
        }
    }
    rumble_countdown_offset_2 = GAME_VAR(rumble_countdown_offset);
    if (rumble_countdown_offset_2 != GAME_VAR(rumble_countdown_offset_placed)) {
        sp10 = rumble_countdown_offset_2 + 0x172;
        sp12 = 0xBE;
        GAME_VAR(rumble_countdown_offset_placed) = rumble_countdown_offset_2;
        sp14 = 0;
        sp24 = 0xFF;
        sp25 = 0xFF;
        sp26 = 0xFF;
        sp27 = 0xFF;
        sp18 = 1.0f;
        sp1C = 1.0f;
        sp20 = 1.0f;
        unused = lift_call<f32>(ctx, n64::place_hud_quad_points)(field::var::rumble_countdown_panel_bone, field::var::rumble_countdown_frame_part, (s32) &sp10);
        sp12 -= 4;
        lift_call<f32>(ctx, n64::place_hud_quad_points)(field::var::rumble_countdown_number_bone, field::var::rumble_countdown_part, (s32) &sp10);
    }
}

