// Gives the menus' camera its table of moves `moves` (kept at 0x80104470: 8-byte entries, a list of six paths and the from- and to-page as 16-bit numbers at +4 and +6, ended by a 0 word; move_menu_camera searches it): counts the first move's six paths (count_path_points, to 0x80104510), puts the camera's six values (0x80104540: x, y, z and the three angles) at each path's last point, marks none as moving (0x80104528), and resets the page (0x801044D4 = 0), 0x801044D8, 0x800F5590 = 0x21 and the shot memory 0x800F5594 = -1.
// From the N64 function at 0x800E18E4 (54 instructions).
// Called by: start_editor_scene, start_scene_overlay, start_menus.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 7 comparisons, no difference (caller twin v11, 0.84, menu_from_attract, select_wcw; see the header's caller-twin note).
void set_menu_camera_paths(recomp_context* ctx, P<P<s32>> moves) {
    LiftFrame frame(ctx, 0x28);
    frame.keep(0x20, ctx->r20);
    frame.keep(0x1C, ctx->r19);
    frame.keep(0x24, ctx->r31);
    frame.keep(0x18, ctx->r18);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x10, ctx->r16);
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    P<f32> values;
    s32 last_path_value;
    P<s32> paths;
    P<s32> counts;
    P<s32> moving;
    s32 path;
    s32 path_points_count;
    s32 loop_again;
    s32 path_points_count_2;
    s32 paths_value;
    s32 i;

    i = 0;
    moving = (P<s32> )field::var::menu_camera_path_directions;
    paths = *moves;
    values = (P<f32> )field::var::menu_camera_values;
    counts = (P<s32> )field::var::menu_camera_path_counts;
    GAME_VAR_AS(menu_camera_moves, P<P<s32>>) = moves;
    GAME_VAR(menu_camera_move) = 0;
    do {
        path = *paths;
        i += 1;
        path_points_count = lift_call<s32>(ctx, n64::count_path_points)(path);
        path_points_count_2 = path_points_count;
        *counts = path_points_count_2;
        paths_value = *paths;
        last_path_value = M2C_FIELD((path_points_count_2 * 4) + paths_value, P<s16> , -4);
        paths += 4;
        counts += 4;
        *values = (f32) last_path_value;
        *moving = 0;
        moving += 4;
        loop_again = i < 6;
        lift_out_v0 = loop_again;
        values += 4;
    } while (loop_again != 0);
    GAME_VAR(menu_camera_fov) = 0x21;
    lift_out_v0 = -1;
    GAME_VAR(menu_camera_focus_state) = 0;
    GAME_VAR(camera_shot_memory) = -1;
}

