    f32 var_f24;
    f64 double_801032b0;
    s32 integer_atan2;
    s32 integer_atan2_2;

    temp_f24 = VEC3F(point, x) - VEC3F(from, x);
    temp_f20 = VEC3F(point, z) - VEC3F(from, z);
    point_y = VEC3F(point, y);
    across = point_y - (f32) VEC3F(from, y);
    integer_atan2 = lift_call<s32>(ctx, n64::integer_atan2)(LIFT_TRUNC_W_S(across), LIFT_TRUNC_W_S(lift_call<f32>(ctx, n64::square_root)((temp_f24 * temp_f24) + (temp_f20 * temp_f20))));
