            unpack_bits_result_2 = lift_call<s32>(ctx, n64::unpack_bits)((s32) bits_2, (s32) saved_title_bytes, (s32) &bit_pos);
            M2C_FIELD(record_at_3, P<s8> , -2) = unpack_bits_result_2;
            bits_3 = M2C_FIELD((P<void> )field::var::title_save_bit_widths, P<u8> , 2);
            unpack_bits_result_3 = lift_call<s32>(ctx, n64::unpack_bits)((s32) bits_3, (s32) saved_title_bytes, (s32) &bit_pos);
            M2C_FIELD(record_at_3, P<s8> , -3) = unpack_bits_result_3;
            bits_4 = M2C_FIELD((P<void> )field::var::title_save_bit_widths, P<u8> , 3);
            unpack_bits_result_4 = lift_call<s32>(ctx, n64::unpack_bits)((s32) bits_4, (s32) saved_title_bytes, (s32) &bit_pos);
            M2C_FIELD(record_at_3, P<s8> , -1) = unpack_bits_result_4;
