            unused_3 = lift_call<s32>(ctx, n64::pack_bits)((s32) M2C_FIELD(record_at_2, P<u8> , -3), (s32) M2C_FIELD((P<void> )field::var::title_save_bit_widths, P<u8> , 2), var_s1, (s32) &sp10);
            unused_4 = lift_call<s32>(ctx, n64::pack_bits)((s32) M2C_FIELD(record_at_2, P<u8> , -1), (s32) M2C_FIELD((P<void> )field::var::title_save_bit_widths, P<u8> , 3), var_s1, (s32) &sp10);
            value = M2C_FIELD(record_at_2, P<u16> , 0);
