            record_at_2 += 8;
            var_s1 += 6;
            lift_call<s32>(ctx, n64::pack_bits)((s32) value, (s32) M2C_FIELD((P<void> )field::var::title_save_bit_widths, P<u8> , 4), buffer, (s32) &sp10);
