    unpack_bits_result_3 = lift_call<s32>(ctx, n64::unpack_bits)((s32) bits_4, packed, (s32) &bit_pos);
    M2C_FIELD(preset, P<s8> , 0x1D) = unpack_bits_result_3;
    bits_5 = GAME_VAR(preset_bit_width_11);
    unpack_bits_result_4 = lift_call<s32>(ctx, n64::unpack_bits)((s32) bits_5, packed, (s32) &bit_pos);
    M2C_FIELD(preset, P<u8> , 0x1E) = unpack_bits_result_4;
