// Packs the 0x22-byte preset `preset` into 9 bytes of bits at `packed` (cleared first): its type (+0xE), then its Superstars as ordinals (func_8000AE78, ID to ordinal; mod/src/roster.c) and the rest, widths from 0x800F5E38. mod/src/save.c reads the same packing (type 5 bits first). Caller write_presets_to_save. (2026-11-13, names5: confirmed from the lifted C++: the reverse of unpack_preset (confirmed): zero_bytes, then the fields written as bits by the same width table 0x800F5E38).
// From the N64 function at 0x800E40B8 (88 instructions).
// Called by: write_presets_to_save.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void pack_preset(recomp_context* ctx, s32 packed, P<void> preset) {
    LiftFrame frame(ctx, 0x38);
    frame.keep(0x24, ctx->r19);
    frame.keep(0x2C, ctx->r21);
    frame.keep(0x30, ctx->r31);
    frame.keep(0x28, ctx->r20);
    frame.keep(0x20, ctx->r18);
    frame.keep(0x1C, ctx->r17);
    frame.keep(0x18, ctx->r16);
    Ref<s32> bit_pos(frame.at(0x10));
    s32 preset_at_half_2;
    s32 unused;
    s32 value_2;
    s32 unused_2;
    s32 unused_3;
    s32 unused_4;
    s32 unused_5;
    s32 unused_6;
    s32 unused_7;
    s32 packed_superstar;
    s32 i;
    P<u8> entry_at_2;
    P<u8> entry_at;
    s32 value;
    s32 value_3;
    s32 bits;
    u32 bits_2;
    u32 bits_3;
    P<void> preset_at;

    bit_pos = 0;
    unused = lift_call<s32>(ctx, n64::zero_bytes)(packed, 9);
    value = M2C_FIELD(preset, P<u8> , 0xE);
    bits = GAME_VAR(preset_field_widths);
    i = 0;
    entry_at = (P<u8> )field::var::preset_field_widths + 2;
    entry_at_2 = (P<u8> )field::var::preset_field_widths + 1;
    preset_at = preset;
    lift_call<s32>(ctx, n64::pack_bits)((s32) value, (s32) bits, packed, (s32) &bit_pos);
    do {
        preset_at_half_2 = M2C_FIELD(preset_at, P<s16> , 2);
        preset_at += 2;
        value_2 = lift_call<s32>(ctx, n64::superstar_to_ordinal)((s32) preset_at_half_2);
        bits_2 = *entry_at_2;
        entry_at_2 += 2;
        unused_2 = lift_call<s32>(ctx, n64::pack_bits)(value_2, (s32) bits_2, packed, (s32) &bit_pos);
        value_3 = M2C_FIELD((preset + i), P<u8> , 0xA);
        bits_3 = *entry_at;
        entry_at += 2;
        i += 1;
        unused_3 = lift_call<s32>(ctx, n64::pack_bits)((s32) value_3, (s32) bits_3, packed, (s32) &bit_pos);
    } while (i < 4);
    unused_4 = lift_call<s32>(ctx, n64::pack_bits)((s32) M2C_FIELD(preset, P<u8> , 0x1C), (s32) GAME_VAR(preset_bit_width_9), packed, (s32) &bit_pos);
    unused_5 = lift_call<s32>(ctx, n64::pack_bits)((s32) M2C_FIELD(preset, P<u8> , 0x1D), (s32) GAME_VAR(preset_bit_width_10), packed, (s32) &bit_pos);
    unused_6 = lift_call<s32>(ctx, n64::pack_bits)((s32) M2C_FIELD(preset, P<u8> , 0x1E), (s32) GAME_VAR(preset_bit_width_11), packed, (s32) &bit_pos);
    if ((M2C_FIELD(preset, P<u8> , 0xE) == 2) && (M2C_FIELD(preset, P<u8> , 0x1E) != 5)) {
        packed_superstar = lift_call<s32>(ctx, n64::superstar_to_ordinal)((s32) M2C_FIELD(preset, P<u16> , 0x20));
    } else {
        packed_superstar = M2C_FIELD(preset, P<u16> , 0x20);
    }
    unused_7 = lift_call<s32>(ctx, n64::pack_bits)(packed_superstar, (s32) GAME_VAR(preset_bit_width_12), packed, (s32) &bit_pos);
}

// Puts the presets into the save image (*0x800F6134): 0xF9 bytes from +0x6E60 zeroed, the two 0x14-character names from `names` and `names` + 0x16 packed 7 bits a character (pack_text_7bit) at +0x6E60 / +0x6E72, the three bytes `names` +0x2C..+0x2E at +0x6F56..+0x6F58, then for each card entry (0x800BD5A8, 0x22 bytes each) its first byte, the entry packed (pack_preset) and its rules (pack_rules, by the kind byte 0x800F5E24[entry's byte before the rules]) from +0x6E84 on. Named from mod/gen/checksave.py, which calls it with the names table as the second of the game's three save writers. (2026-11-12, names3: confirmed and the layout read from the lifted C++.)
// From the N64 function at 0x800E4218 (61 instructions).
// Called by: clear_card, return_to_card_after_match, card_page_edit_action.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void write_presets_to_save(recomp_context* ctx, s32 names) {
    LiftFrame frame(ctx, 0x28);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x18, ctx->r18);
    frame.keep(0x24, ctx->r31);
    frame.keep(0x20, ctx->r20);
    frame.keep(0x1C, ctx->r19);
    frame.keep(0x10, ctx->r16);
    s32 unused;
    s32 unused_2;
    s32 saved_presets;
    s32 i;
    P<u8> record_at;
    P<u8> preset_at;
    s32 kind;
    P<void> rows;
    P<void> save_image;
    P<void> preset_rules_at;

    save_image = GAME_VAR(save_image);
    saved_presets = (s32) (save_image + 0x6E60);
    lift_call<s32>(ctx, n64::zero_bytes)(saved_presets, 0xF9);
    lift_call<s32>(ctx, n64::pack_text_7bit)(saved_presets, names, 0x14);
    unused = lift_call<s32>(ctx, n64::pack_text_7bit)(save_image + 0x6E72, names + 0x16, 0x14);
    SAVE_IMAGE(save_image, preset_byte_0) = (u8) M2C_FIELD(names, P<u8> , 0x2C);
    i = 0;
    preset_at = (P<u8> )0x800BD5A8;
    SAVE_IMAGE(save_image, preset_byte_1) = (u8) M2C_FIELD(names, P<u8> , 0x2D);
    record_at = save_image + 0x6E84;
    preset_rules_at = (P<void> )field::var::card_entry_rules;
    SAVE_IMAGE(save_image, preset_byte_2) = (s32) M2C_FIELD(names, P<u8> , 0x2E);
    do {
        *record_at = *preset_at;
        rows = preset_rules_at;
        kind = GAME_TABLE(card_entry_rules_kinds, M2C_FIELD(preset_rules_at, P<u8> , -1));
        i += 1;
        preset_rules_at += 0x22;
        lift_call<s32>(ctx, n64::pack_rules)((s32) (record_at + 0xA), (s32) rows, (s32) kind);
        lift_call<s32>(ctx, n64::pack_preset)((s32) (record_at + 1), (s32) preset_at);
        record_at += 0xE;
        preset_at += 0x22;
    } while (i < 0xF);
    unused_2 = lift_call<s32>(ctx, n64::write_save)();
}

// Reads the presets back from the save image: two 20-character names (7-bit packed at image + 0x6E60 and + 0x6E72) to `names` + 0 and + 0x16, three bytes from + 0x6F56 to names + 0x2C, and the 15 presets (image + 0x6E84, 0xE bytes each; mod/src/save.c PRESETS: +0 0xFF unused) into 0x800BD5A8 (0x22 each: +0 the first byte, +0xF the rules from + 0xA (unpack_rules), the rest by unpack_preset (func_800E3F64)). The reverse of write_presets_to_save; what the two names are isn't established. Callers include build_controller_pak_menu.
