// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void load_presets_from_save(recomp_context* ctx, s32 names) {
    LiftFrame frame(ctx, 0x28);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x20, ctx->r31);
    frame.keep(0x1C, ctx->r19);
    frame.keep(0x18, ctx->r18);
    s32 unused;
    s32 unused_2;
    s32 i;
    P<u8> saved;
    P<u8> preset;
    P<void> save_image;

    save_image = GAME_VAR(save_image);
    lift_call<s32>(ctx, n64::zero_bytes)(names, 0x36);
    preset = (P<u8> )0x800BD5A8;
    lift_call<s32>(ctx, n64::zero_bytes)(0x800BD5A8, 0x1FE);
    lift_call<s32>(ctx, n64::unpack_text_7bit)(names, save_image + 0x6E60, 0x14);
    unused = lift_call<s32>(ctx, n64::unpack_text_7bit)(names + 0x16, save_image + 0x6E72, 0x14);
    M2C_FIELD(names, P<u8> , 0x2C) = (u8) SAVE_IMAGE(save_image, preset_byte_0);
    M2C_FIELD(names, P<u8> , 0x2D) = (u8) SAVE_IMAGE(save_image, preset_byte_1);
    i = 0;
    saved = save_image + 0x6E84;
    M2C_FIELD(names, P<u8> , 0x2E) = (s32) SAVE_IMAGE(save_image, preset_byte_2);
    do {
        i += 1;
        *preset = *saved;
        lift_call<s32>(ctx, n64::unpack_rules)((s32) (saved + 0xA), preset + 0xF);
        unused_2 = lift_call<s32>(ctx, n64::unpack_preset)((s32) (saved + 1), (s32) preset);
        saved += 0xE;
        preset += 0x22;
    } while (i < 0xF);
}

