    money = GAME_VAR(money);
    if ((s32) (money > 0x05F5E0F6) != 0) {
        GAME_VAR(money) = 0x05F5E0F6;
    }
    save_image = GAME_VAR(save_image);
    lift_out_v0 = field::var::hi(field::var::mall_discount_level);
    SAVE_IMAGE(save_image, byte_6b83) = (s32) GAME_VAR(mall_discount_level);
