// Called by: save_to_controller_pak.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void pack_default_created_superstars(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x158);
    frame.keep(0x140, ctx->r18);
    frame.keep(0x14C, ctx->r21);
    frame.keep(0x144, ctx->r19);
    frame.keep(0x148, ctx->r20);
    frame.keep(0x150, ctx->r31);
    frame.keep(0x13C, ctx->r17);
    frame.keep(0x138, ctx->r16);
    Ref<M2C_UNK> sp10(frame.at(0x10));
    Ref<M2C_UNK> sp60(frame.at(0x60));
    s32 temp_a1;
    s32 temp_a1_2;
    s32 pak_buffer;
    s32 unused;
    s32 unused_2;
    s32 unused_3;
    s32 unused_4;
    s32 unused_5;
    s32 unused_6;
    s32 j;
    s32 offset_2;
    s32 i;
    s32 offset;
    s32 record_at;

    i = 0;
    offset = 0;
    record_at = 0x1368;
    lift_call<s32>(ctx, n64::zero_bytes)(GAME_VAR(pak_buffer), 0x2300);
    lift_call<s32>(ctx, n64::load_roster_files)();
    do {
        j = 0;
        offset_2 = 0;
        do {
            unused = lift_call<s32>(ctx, n64::build_costume_record)(i + 0xB01, j, (s32) &sp10);
            j += 1;
            lift_call<s32>(ctx, n64::pack_costume_for_save)(GAME_VAR(pak_buffer) + offset + offset_2, (s32) &sp10);
            offset_2 += 0x44;
        } while (j < 4);
        unused_2 = lift_call<s32>(ctx, n64::load_superstar_moveset)(i + 0xB01, (s32) &sp60);
        unused_3 = lift_call<s32>(ctx, n64::copy_moveset_to_save)(GAME_VAR(pak_buffer) + record_at, (s32) &sp60);
        i += 1;
        temp_a1 = GAME_VAR(pak_buffer) + offset;
        unused_4 = lift_call<s32>(ctx, n64::store_save_checksum)(temp_a1 + 0x110, temp_a1, 0x110);
        offset += 0x114;
        temp_a1_2 = GAME_VAR(pak_buffer) + record_at;
        unused_5 = lift_call<s32>(ctx, n64::store_save_checksum)(temp_a1_2 + 0xD8, temp_a1_2, 0xD8);
        record_at += 0xDC;
    } while (i < 0x12);
    pak_buffer = GAME_VAR(pak_buffer);
    lift_call<s32>(ctx, n64::store_save_checksum)(pak_buffer + 0x22E0, pak_buffer, 0x22E0);
    unused_6 = lift_call<s32>(ctx, n64::free_roster_files)();
}

