// The 0xB0 move slots of a packed moveset: with `packing` set writes each u16 of `moves` into `packed` (pack_bits: the slot's width from the 5-byte table 0x800F6B6C, then its top 3 flag bits), else reads them back (unpack_bits).
// From the N64 function at 0x800E77D8 (57 instructions).
// Called by: pack_moveset_moves, unpack_moveset_moves.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void pack_or_unpack_moveset_moves(recomp_context* ctx, P<u16> moves, s32 packed, s32 packing) {
    LiftFrame frame(ctx, 0x30);
    frame.keep(0x20, ctx->r18);
    frame.keep(0x24, ctx->r19);
    frame.keep(0x18, ctx->r16);
    frame.keep(0x1C, ctx->r17);
    frame.keep(0x28, ctx->r20);
    frame.keep(0x2C, ctx->r31);
    Ref<s32> bit(frame.at(0x10));
    s32 unpack_bits_result;
    s32 moves_end;
    P<u16> move;
    P<u8> slot_def;
    u32 bits;

    move = moves;
    slot_def = (P<u8> )field::var::moveset_move_slot_widths;
    moves_end = (s32) (move + 0x160);
    bit = 0;
    do {
        if (packing != 0) {
            lift_call<s32>(ctx, n64::pack_bits)((s32) *move, (s32) *slot_def, packed, (s32) &bit);
        } else {
            bits = *slot_def;
            *move = lift_call<s32>(ctx, n64::unpack_bits)((s32) bits, packed, (s32) &bit);
        }
        if (packing != 0) {
            lift_call<s32>(ctx, n64::pack_bits)((s32) ((u16) *move >> 0xD), 3, packed, (s32) &bit);
        } else {
            unpack_bits_result = lift_call<s32>(ctx, n64::unpack_bits)(3, packed, (s32) &bit);
            *move |= (unpack_bits_result & 7) << 0xD;
        }
        move += 2;
        slot_def += 5;
    } while ((s32) move < moves_end);
}

