// Position of choice `choice` in the sorted choice list *0x8010642C (count *0x80106448): the matching row, or the row before where it would be.
// From the N64 function at 0x800E834C (21 instructions).
// Called by: moves_page_action.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 find_in_choice_list(s32 choice) {
    s32 row;
    P<u16> entry;
    s32 count;
    u32 entry_value;

    count = GAME_VAR(sorted_choice_list_count);
    row = 0;
    if ((s32) count > 0) {
        entry = GAME_VAR_AS(sorted_choice_list, P<u16>);
        for (;;) {
            entry_value = *entry;
            if (entry_value != choice) {
                if (choice >= (s32) entry_value) {
                    row += 1;
                    entry += 2;
                    if (row < (s32) count) {
                        continue;
                    }
                } else {
                    row -= 1;
                }
            }
            break;
        }
    }
    return row;
}

