// Draws text ID `text`'s lines one by one as the timer 0x8009ED18 reaches each (line n shown from `first` + n), at x `x` + 0x30, y 0x2A + line x 14 (empty lines skipped but counted for spacing).
// From the N64 function at 0x800EA504 (51 instructions).
// Called by: reveal_text_page.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void reveal_text_lines(recomp_context* ctx, s32 text, s32 x, s32 first) {
    LiftFrame frame(ctx, 0x38);
    frame.keep(0x24, ctx->r19);
    frame.keep(0x1C, ctx->r17);
    frame.keep(0x20, ctx->r18);
    frame.keep(0x30, ctx->r31);
    frame.keep(0x2C, ctx->r21);
    frame.keep(0x28, ctx->r20);
    frame.keep(0x18, ctx->r16);
    s32 first_line;
    s32 skip_text_line_result;
    s32 line;
    s32 y;
    s32 shown_from;
    u32 first_char;

    shown_from = first;
    first_line = lift_call<s32>(ctx, n64::text_id_string)(text);
    line = first_line;
    if (line != 0) {
        first_char = M2C_FIELD(line, P<u8> , 0);
        if (first_char != 0) {
            y = (first * 0xE) + 0x2A;
            for (;;) {
                if (GAME_VAR(front_end_timer) >= shown_from) {
                    if (first_char != 0xA) {
                        lift_call<s32>(ctx, n64::request_text_item)(line, x + 0x30, y, 0x31, 4);
                        shown_from += 1;
                    }
                    skip_text_line_result = lift_call<s32>(ctx, n64::skip_text_line)(line);
                    line = skip_text_line_result;
                    first_char = M2C_FIELD(line, P<u8> , 0);
                    y += 0xE;
                    if (first_char != 0) {
                        continue;
                    }
                }
                break;
            }
        }
    }
}

