// The codes the entrances hand the ring-announcer subsystem (stored in 0x800A8730 for send_match_rule_codes): low byte the match's standing (4 with match flag 0x800A957C 0x100000; 1 outside a game mode (0x800A9578 0); for mode 2 (the match card, 15 records 0x800BD5A8) 3 for the last match, 2 the one before, else the match + 5; 0 other modes), high byte from the match kind bits 0x800A957C & 0xFFF (1 -> 1, 2 -> 2, 0x200 -> 3, else 4). (2026-11-12, names4: confirmed from the lifted C++: the name says only what the code does).
// From the N64 function at 0x800EA5F0 (59 instructions).
// Called by: run_front_end_sequence_step.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 entrance_match_codes(void) {
    s32 standing;
    s32 offset;
    s32 kind;
    s32 kind_shifted;
    s32 matches;
    s32 current_match;
    s32 menu_context;
    u32 match_type_low_12_bits;

    standing = 0;
    if (GAME_VAR(match_type) & 0x100000) {
        standing = 4;
    } else {
        menu_context = GAME_VAR(menu_context);
        if (menu_context != 0) {
            matches = 0;
            if (menu_context == 2) {
                offset = 0;
                for (;;) {
                    if (GAME_TABLE(card_matches_in_use, offset) != 0) {
                        matches += 1;
                        offset += 0x22;
                        if (matches < 0xF) {
                            continue;
                        }
                    }
                    break;
                }
                current_match = *(P<s8> )0x800A5710;
                if (current_match == (matches - 1)) {
                    standing = 3;
                } else {
                    standing = current_match + 5;
                    if (current_match == (matches - 2)) {
                        standing = 2;
                    }
                }
            }
        } else {
            standing = 1;
        }
    }
    kind_shifted = 0 << 8;
    if (0 == 0) {
        match_type_low_12_bits = GAME_VAR(match_type) & 0xFFF;
        if (match_type_low_12_bits == 2) {
            kind = 2;
        } else if (match_type_low_12_bits < 3U) {
            kind = 1;
            if (match_type_low_12_bits != 1) {
                kind = 4;
            }
        } else {
            kind = 3;
            if (match_type_low_12_bits != 0x200) {
                kind = 4;
            }
        }
        kind_shifted = kind << 8;
    }
    return standing | kind_shifted;
}

// A value for the current sequence 0x800A872C, read as its song: 0 for 0x38-0x3C, 0x50, 0x52, 0x55, 0x61-0x63; 10 for 0x2A; 0x800A10D4 (start_save_screen's kind) for 0x56 / 0x57; -1 for 0x59-0x60, 0x64-0x69, 0x6B; any other stops the music (func_80017C64(0, fade 8 for 0x58, 16 for 0x6D / 0x6E, else 0)) and gives -1. No converted callers; that the value is a song is a reading of the func_80017C64 call. (2026-11-14, fablenames2: read line by line; left a guess. The code is as the about says. func_80017C64 has no entry here; mod/src/arcade.h calls it 'a song played' (GF_PLAY_SONG) and its abouts' mentions (start_music, set_music_volume) agree, so func_80017C64(0, fade, 0) is read as 'song 0 with a fade'. What the returned value is used for stays unknown: there is no caller in the converted code and no mention of the address in the mod's sources or the port's code (hints.py: 0 hits).)
// From the N64 function at 0x800EA6DC (38 instructions). The name is a best guess from the code alone.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 sequence_song_code(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x14, ctx->r31);
    s32 front_end_sequence;
    s32 fade;
    s32 song;

    front_end_sequence = GAME_VAR(front_end_sequence);
    song = -1;
    switch (front_end_sequence) {
    case 0x38:
    case 0x39:
    case 0x3A:
    case 0x3B:
    case 0x3C:
    case 0x50:
    case 0x52:
    case 0x55:
    case 0x61:
    case 0x62:
    case 0x63:
        song = 0;
    case 0x59:
    case 0x5A:
    case 0x5B:
    case 0x5C:
    case 0x5D:
    case 0x5E:
    case 0x5F:
    case 0x60:
    case 0x64:
    case 0x65:
    case 0x66:
    case 0x67:
    case 0x68:
    case 0x69:
    case 0x6B:
        return song;
    case 0x56:
    case 0x57:
        return GAME_VAR(save_screen_kind);
    case 0x58:
        fade = 8;
        lift_call<s32>(ctx, n64::play_music_song)(0, fade, 0);
        return song;
    case 0x2A:
        song = 0xA;
        return song;
    case 0x6D:
    case 0x6E:
        fade = 0x10;
        lift_call<s32>(ctx, n64::play_music_song)(0, fade, 0);
        return song;
    default:
        fade = 0;
        lift_call<s32>(ctx, n64::play_music_song)(0, fade, 0);
        return song;
    }
}

