// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 115 comparisons, no difference (leaf twin, 0.84, match_tag, menu_from_attract, rules_single_hardcore, smoke_singles).
s32 still_counts_in_match(P<void> wrestler) {
    s32 result;
    s32 match_flags;

    if ((GAME_VAR(match_flags) & 0x4000) && (GAME_VAR(match_rules) & 0x400) && (WRESTLER(wrestler, control_flags) & 0x10) && (WRESTLER(wrestler, area_bits) & 4)) {
        return 0;
    }
    match_flags = WRESTLER(wrestler, match_flags);
    result = 1;
    if (match_flags & 0x41) {
        result = (match_flags & 2) != 0;
    }
    return result;
}

