// Returns 0 when some wrestler is going out through the ropes or climbing in (110 / 111) with +0x84 bit 2 (side 0) or bit 3 (side 1) set, else 1. Used by try_c_up_at_ropes and state 140 before using that side. Reading: the bits mark which ring side / steps the climb uses.
// From the N64 function at 0x800EDC84 (28 instructions).
// Has gotos where m2c couldn't find the loop or the if: its structure is to be tidied by hand.
// Called by: try_c_up_at_ropes, wrestler_state_140_weapon_pull_b.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 no_one_at_ring_steps(recomp_context* ctx, s32 side) {
    s32 count_in_gp;
    s32 offset;
    s32 i;
    s32 result;
    s32 steps_bit;
    P<u16> record_at;

    count_in_gp = ((s32)ctx->r28);
    i = 0;
    record_at = (P<u16> )field::var::wrestlers_0_state_counter;
    offset = 0;
    for (;;) {
        if ((u32) (WRESTLER_IN(wrestlers, offset, state) - 0x6E) < 2U) {
            if (side == 0) {
                steps_bit = *record_at & 4;
            } else {
                steps_bit = *record_at & 8;
            }
            result = 0;
            if (steps_bit == 0) {
                goto block_6;
            }
        } else {
block_6:
            record_at += 0x358;
            i += 1;
            offset += 0x358;
            if (i >= count_in_gp) {
                result = 1;
            } else {
                continue;
            }
        }
        break;
    }
    return result;
}

// A story node's rank condition (the result field masked 0x70): -1 when it holds, 1 when not. mod/src/arcade.h GF_COND_RANK, mod/NOTES.md.
// From the N64 function at 0x800EDD84 (49 instructions).
// Called by: story_branch.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 story_rank_condition(u32 bits) {
    s32 temp_a2;
    s32 match_result_bits_bit0;
    s32 offset;
    s32 var_a2;
    s32 i;
    s32 result;
    s32 var_v0;
    s32 match_rating_entry;
    s32 temp_v1;

    result = 1;
    var_a2 = GAME_VAR(entrant_list_count);
    i = 0;
    offset = 0;
    do {
        match_rating_entry = GAME_TABLE(match_rating, offset);
        temp_v1 = GAME_TABLE(slot_tally_cpu_count, offset);
        offset += 0x1C;
        i += 1;
        var_a2 = (var_a2 - match_rating_entry) - temp_v1;
    } while (i < 4);
    match_result_bits_bit0 = GAME_VAR(match_result_bits) & 1;
    temp_a2 = var_a2 + (match_result_bits_bit0 == 0);
    if (bits != 0x20) {
        if (bits < 0x21U) {
            if ((bits == 0x10) && (match_result_bits_bit0 != 0)) {
                result = -1;
            }
        } else if (bits != 0x30) {
            if (bits == 0x40) {
                var_v0 = temp_a2 < 0x19;
                if (var_v0 != 0) {
                    result = -1;
                }
            }
        } else {
            var_v0 = temp_a2 < 0x10;
            if (var_v0 != 0) {
                result = -1;
            }
        }
    } else {
        var_v0 = temp_a2 < 0xD;
        if (var_v0 != 0) {
            result = -1;
        }
    }
    return result;
}

