    P<s32> entry_at_3;
    P<s32> entry_at;
    s32 copied_8;
    s32 entry_at_value;
    s32 temp_a0_3;
    s32 entry;
    s32 copied_c;
    s32 entrant_list_count;
    s32 temp_v0_3;
    s32 copied_4;
    s32 var_a3;
    s32 i;
    s32 var_v1;
    u32 var_v0;

    copied_4 = M2C_FIELD((P<void> )field::var::rumble_history_order_start, P<s32> , 4);
    copied_8 = M2C_FIELD((P<void> )field::var::rumble_history_order_start, P<s32> , 8);
    sp0 = GAME_VAR(rumble_history_order_start);
    sp4 = copied_4;
    sp8 = copied_8;
    copied_c = M2C_FIELD((P<void> )field::var::rumble_history_order_start, P<s32> , 0xC);
    spC = copied_c;
    i = 0;
    entry_at = P<void>(frame.at(0));
    do {
        var_a3 = i;
        if (i < 4) {
            entry_at_2 = (i * 4) + P<void>(frame.at(0));
            do {
                entry = *entry_at;
                entry_at_value = *entry_at_2;
                var_a3 += 1;
                if ((u32) GAME_ARRAY_AS(slot_elimination_seconds, (entry * 4), u32) < (u32) GAME_ARRAY_AS(slot_elimination_seconds, (entry_at_value * 4), u32)) {
                    *entry_at = entry_at_value;
                    *entry_at_2 = entry;
                }
                entry_at_2 += 4;
            } while (var_a3 < 4);
        }
        i += 1;
        entry_at += 4;
    } while (i < 3);
    record_at = record;
    entrant_list_count = GAME_VAR(entrant_list_count);
    entry_at_3 = P<void>(frame.at(0));
    do {
        if (entrant_list_count >= 5) {
            temp_a0_3 = GAME_TABLE(slot_result_entrant, (*entry_at_3 * 0x1C)) & 7;
            var_v0 = GAME_TABLE(entrant_costumes, temp_a0_3);
            var_v1 = GAME_ARRAY(entrant_ids, (temp_a0_3 * 2)) & 0xFFF;
        } else {
            temp_v0_3 = (*entry_at_3 & 3) * 4;
            var_v0 = GAME_ARRAY(match_slot_costumes, temp_v0_3);
            var_v1 = GAME_ARRAY(match_slot_superstars, temp_v0_3) & 0xFFF;
        }
        *record_at = var_v1 | (var_v0 << 0xC);
        record_at += 2;
        entry_at_3 += 4;
    } while ((s32) record_at < (s32) (record + 8));
