    lift_out_v0 = seconds >> 0x1F;
    seconds_over_60 = seconds / 60;
    lift_out_v0 = seconds_over_60 * 0x3C;
    unused = lift_call<s32>(ctx, n64::menu_text_picture_data)((seconds % 60) + 0x193, palette, pixels);
