// The position of character `character` in the big font's zero-ended character list at 0x80103164 (0 when absent, the same as the first character).
// From the N64 function at 0x800F0B10 (15 instructions).
// Called by: big_font_glyph.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 big_font_glyph_index(s32 character) {
    s32 result;
    P<u8> character_at;
    u32 listed_character;

    character_at = (P<u8> )field::var::big_font_characters;
    result = 0;
    listed_character = GAME_VAR(big_font_characters);
    for (;;) {
        character_at += 1;
        if (listed_character != (character & 0xFF)) {
            listed_character = *character_at;
            result += 1;
            if (listed_character == 0) {
                return 0;
            }
            continue;
        }
        break;
    }
    return result;
}

