// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 2 comparisons, no difference (leaf twin, 0.84, menu_from_attract, smoke_singles).
s32 ai_split_move_list(s32 count, P<s32> usable_out, P<s32> rest_out, P<void> list) {
    P<s32> usable_out_at;
    P<s32> rest_out_at;
    s32 result;
    s32 i;
    P<void> list_at;

    usable_out_at = usable_out;
    rest_out_at = rest_out;
    list_at = list;
    i = 0;
    result = 0;
    if (count > 0) {
        do {
            if (M2C_FIELD(list_at, P<u8> , 2) & 1) {
                result += 1;
                *usable_out_at = (s32) M2C_FIELD(list_at, P<s16> , 0);
                usable_out_at += 4;
            } else {
                *rest_out_at = (s32) M2C_FIELD(list_at, P<s16> , 0);
                rest_out_at += 4;
            }
            i += 1;
            list_at += 4;
        } while (i < count);
    }
    return result;
}

