s32 ai_object_within_reach(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x58);
    frame.keep(0x50, ctx->r31);
    Ref<s32> nearest_object(frame.at(0x10));
    s32 unused;
    s32 result;

    unused = lift_call<s32>(ctx, n64::list_objects_by_distance)(GAME_VAR_AS(ai_wrestler_now, s32) + 0xFC, (s32) &nearest_object);
    result = 0;
    if ((nearest_object != -1) && ((f64) Ref<f32>(frame.at(0x14)) < GAME_VAR(f64_100_6))) {
        result = nearest_object != 6;
    }
    return result;
}

// 1 when the CPU wrestler (*0x8016B8E8) is still in the match (his record +0x94 bit 0 clear) and exactly two wrestlers are out (+0x94 bit 0 set, counted over all the slots). Used by the CPU's plan choosing. Read from the code (second review).
