        break;
    case 0x82:                                      
        code = 0x26;
        break;
    case 0x11:                                      
    case 0x13:                                      
        code = 0x20;
        break;
    case 0x12:                                      
    case 0x14:                                      
        code = 0x21;
        break;
    case 0x55:                                      
    case 0x5D:                                      
    case 0x5F:                                      
        code = 0x2C;
        break;
    case 0x56:                                      
    case 0x5E:                                      
    case 0x60:                                      
