void ai_set_plan(recomp_context* ctx, s32 plan) {
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    s32 state;
    s32 new_ai_flags;
    s32 new_ai_flags_2;
    s32 ai_flags;
    s32 ai_flags_2;
    P<void> ai_again;
    P<void> target;
    P<void> ai;

    ai = GAME_VAR(ai_record_now);
    target = GAME_VAR(ai_target_now);
    ai_flags = AI_RECORD(ai, ai_flags);
    AI_RECORD(ai, plan) = plan;
    AI_RECORD(ai, plan_step) = 0;
    AI_RECORD(ai, plan_substep) = 0;
    state = WRESTLER(target, state);
    new_ai_flags = ai_flags & 0xFC;
    AI_RECORD(ai, ai_flags) = (u8) new_ai_flags;
    ai_again = GAME_VAR(ai_record_now);
    AI_RECORD(ai, target_state_at_plan) = (s16) state;
    ai_flags_2 = AI_RECORD(ai_again, ai_flags);
    new_ai_flags_2 = ai_flags_2 | 1;
    lift_out_v0 = new_ai_flags_2;
    AI_RECORD(ai_again, ai_flags) = (u8) new_ai_flags_2;
}

