    f32 ai_noisy_estimate_result_2;
    f32 ai_noisy_estimate_result_3;
    f32 ai_noisy_estimate_result_4;
    f32 new_estimate_of_68;
    f32 ai_noisy_estimate_result_5;
    f32 ai_noisy_estimate_result_6;
    f32 ai_noisy_estimate_result_7;
    s32 i_offset;
    s32 temp_v0_3;
    s32 var_a0;
    s32 var_a0_2;
    s32 i;
