// Moves the entrance sequence 0x800A872C on: to 0x1A (the skip) when the step state 0x800A10D4 has 0x80, by `skip` with 0x40, else by 1, through func_80109F88(step, 0) (which picks the step actually played); clears 0x800A9418 / 0x800A10D4 / 0x8009ED18 / 0x800A93C4.
// From the N64 function at 0x8010A7CC (37 instructions).
// Called by: run_entrance_step.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void advance_entrance_sequence(recomp_context* ctx, s32 skip) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r31);
    s32 save_request;
    s32 new_front_end_sequence;
    s32 save_screen_kind;
    s32 next_step;

    save_screen_kind = GAME_VAR(save_screen_kind);
    if (save_screen_kind & 0x80) {
        next_step = 0x1A;
    } else if (save_screen_kind & 0x40) {
        next_step = GAME_VAR(front_end_sequence) + skip;
    } else {
        next_step = GAME_VAR(front_end_sequence) + 1;
    }
    GAME_VAR(save_request) = next_step;
    save_request = GAME_VAR(save_request);
    new_front_end_sequence = lift_call<s32>(ctx, n64::pick_entrance_step)(save_request, 0);
    GAME_VAR(front_end_sequence) = new_front_end_sequence;
    GAME_VAR(save_state) = 0;
    GAME_VAR(save_screen_kind) = 0;
    GAME_VAR(front_end_timer) = 0;
    GAME_VAR(save_request) = 0;
}

