// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 59 comparisons, no difference (caller twin v11, 0.84, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, select_wcw; see the header's caller-twin note).
s32 first_free_costume(recomp_context* ctx, s32 id) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x18, ctx->r31);
    s32 costume_taken;
    s32 i;

    i = 0;
    for (;;) {
        costume_taken = lift_call<s32>(ctx, n64::costume_taken)(id, i);
        if (costume_taken != 0) {
            i += 1;
            if (i >= 4) {
                return -1;
            }
            continue;
        }
        break;
    }
    return i;
}

