    s32 ability_bits_bit22;
    s32 new_plan_step;
    s32 target_situation;
    s32 target_running;
    s32 wrestler_2;
    s32 stick_toward_apron;
    s32 ai_flags_bit6;
    s32 own_situation_3;
    s32 wrestler_3;
    s32 magnitude_below_1025;
