        lift_call<s32>(ctx, n64::menu_widget_command)(0, i + 0x17, 0xF, 5, 0, 0);
        lift_call<s32>(ctx, n64::menu_widget_command)(0, i + 0x1D, 0xF, 5, 0, 0);
