// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 7 comparisons, no difference (leaf twin, 0.84, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, select_wcw).
void clear_screen_history(void) {
    P<s16> entry_at;
    s32 left;

    GAME_VAR(screen_history_count) = 0;
    left = 0x3F;
    entry_at = (P<s16> )field::var::screen_history_last;
    do {
        *entry_at = 0;
        left -= 1;
        entry_at -= 2;
    } while (left >= 0);
}

// Music for the entrance step 0x800A872C: steps 2 / 8 / 14 / 20 song 0 for 2 frames, then 0x41, 3 / 9 / 15 / 21 entrant_entrance_song(time), 4-7 / 10-13 / 16-19 / 22-25 entrant_entrance_song(time + 0x200), 0x23 / 0x24 / 0x28 0x80133B84, some steps song 0, 0x1F-0x22 nothing, any other stops it (func_80017C64(song, 0x20, 0x50)); then the step time 0x80133B88 advances by 0x801064C0.
// From the N64 function at 0x8010B5BC (58 instructions).
// Called by: run_entrance_step.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void play_entrance_music(recomp_context* ctx) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x14, ctx->r31);
    s32 front_end_sequence;
    s32 entrant;
    s32 song;

    front_end_sequence = GAME_VAR(front_end_sequence);
    song = -1;
    switch (front_end_sequence) {
    case 0x1F:
    case 0x20:
    case 0x21:
    case 0x22:
        break;
    case 0x2:
    case 0x8:
    case 0xE:
    case 0x14:
        song = -(GAME_VAR(front_end_timer) >= 2) & 0x41;
        break;
    case 0x3:
    case 0x9:
    case 0xF:
    case 0x15:
        entrant = GAME_VAR(front_end_timer);
        song = lift_call<s32>(ctx, n64::entrant_entrance_song)(entrant);
        break;
    case 0x4:
    case 0x5:
    case 0x6:
    case 0x7:
    case 0xA:
    case 0xB:
    case 0xC:
    case 0xD:
    case 0x10:
    case 0x11:
    case 0x12:
    case 0x13:
    case 0x16:
    case 0x17:
    case 0x18:
    case 0x19:
        entrant = GAME_VAR(front_end_timer) + 0x200;
        song = lift_call<s32>(ctx, n64::entrant_entrance_song)(entrant);
        break;
    case 0x1A:
    case 0x1B:
    case 0x1C:
    case 0x1E:
    case 0x38:
    case 0x39:
    case 0x3A:
    case 0x3B:
    case 0x3C:
    case 0x50:
    case 0x52:
    case 0x55:
    case 0x61:
    case 0x62:
    case 0x63:
        song = 0;
        break;
    case 0x23:
    case 0x24:
    case 0x28:
        song = GAME_VAR(after_match_song);
        break;
    default:
        lift_call<s32>(ctx, n64::play_music_song)(0, 0, 0);
        break;
    }
    if (song >= 0) {
        lift_call<s32>(ctx, n64::play_music_song)((s32) (s16) song, 0x20, 0x50);
    }
    GAME_VAR(entrance_step_time) = (s32) (GAME_VAR(entrance_step_time) + GAME_VAR(front_end_frame_ticks));
}

// Records a screen in the menus' history: a 64-entry ring of s16 at 0x80158218 (count 0x8015832C), entry = `screen` | `cursor` << 8. confirm_menu_item pushes the current screen (0x800457A4) and its cursor.
