// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 3 comparisons, no difference (leaf twin, 0.84, modes_reg_rumble (match not reached)).
void push_screen_history(s32 screen, s32 cursor) {
    s32 screen_history_count_u16_plus_1;
    u32 screen_history_count_u16;

    if (GAME_VAR(screen_history_count) < 0) {
        GAME_VAR(screen_history_count) = 0;
    }
    screen_history_count_u16 = (u16) GAME_VAR_AS(screen_history_count, u16);
    screen_history_count_u16_plus_1 = screen_history_count_u16 + 1;
    GAME_VAR(screen_history_count) = screen_history_count_u16_plus_1;
    GAME_TABLE(screen_history, ((s32) (screen_history_count_u16 << 0x10) >> 0xF)) = (s16) (screen | (cursor << 8));
    if ((s32) (s16) screen_history_count_u16_plus_1 >= 0x40) {
        GAME_VAR(screen_history_count) = 0;
    }
}

// The screen `back` entries back in the menus' history (push_screen_history), -1 when there are not that many.
// From the N64 function at 0x8010B63C (12 instructions).
// Called by: menu_start_skip_ahead, menu_back_action, do_menu_action, draw_menu_page_decoration and 2 more.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
u32 previous_screen(s32 back) {
    s32 entry_index;

    entry_index = GAME_VAR(screen_history_count) - back;
    if (entry_index <= 0) {
        return -1U;
    }
    return GAME_TABLE(screen_history_screen_bytes, (entry_index * 2));
}

