// Looks ahead from script position `position` (0x80125CF8 + 4 x position) through the commands that don't wait for a place command (op 0x10): transition 1 -> fade target 0x80133C74 = 0xFF, 2 -> -0xFF, else 0 (0xFF when the scene is being skipped, 0x80133C46); fade step 0x80133C78 = 0x20; after effect 4 (0x80133C8A) the fade 0x801056D0 takes it at once. Returns the target.
// From the N64 function at 0x8010DEB0 (58 instructions).
// Called by: wait_scene_command.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 scene_fade_for_next_place(s32 position) {
    s32 skipping;
    s32 position_offset;
    s32 entry_at_half_1;
    P<u8> command;
    u32 op;
    P<void> entry_at;

    position_offset = position * 4;
    skipping = GAME_VAR(scene_skipped);
    command = position_offset + field::var::scene_script_commands;
    GAME_VAR(scene_fade_target) = 0;
    GAME_VAR(scene_fade_step) = 0x20;
    if (skipping != 0) {
        GAME_VAR(scene_fade_target) = 0xFF;
    } else {
        op = GAME_ARRAY_AS(scene_script_commands, position_offset, u8);
        entry_at = command + 1;
        if (op != 0) {
            for (;;) {
                if ((op & 0xF0) == 0x10) {
                    entry_at_half_1 = M2C_FIELD(entry_at, P<u16> , 1);
                    if (entry_at_half_1 != 1) {
                        if (entry_at_half_1 == 2) {
                            GAME_VAR(scene_fade_target) = -0xFF;
                        }
                    } else {
                        GAME_VAR(scene_fade_target) = 0xFF;
                    }
                }
                if (M2C_FIELD(entry_at, P<u8> , 0) == 0) {
                    command += 4;
                    op = *command;
                    entry_at += 4;
                    if (op != 0) {
                        continue;
                    }
                }
                break;
            }
        }
    }
    if (GAME_VAR(scene_running_effect) == 4) {
        GAME_VAR(screen_fade) = GAME_VAR(scene_fade_target);
    }
    return GAME_VAR(scene_fade_target);
}

