            temp_f2_2 = (f64) var_f12;
            if (GAME_VAR(f64_130_29) <= temp_f2_2) {
                var_condition_bit = temp_f2_2 < GAME_VAR(f64_180_12);
                if (var_condition_bit) {
                    var_a0 = 1;
                }
            }
