        cursor = gfx + 8;
        GFX(gfx, w0) = 0xFD100000;
        GFX(gfx, w1) = (s32) (pixels_2 - field::var::kseg0);
        cursor = gfx + 0x10;
        GFX_AT(gfx, 1, w0) = 0xE8000000;
        GFX_AT(gfx, 1, w1) = 0;
        cursor = gfx + 0x18;
        GFX_AT(gfx, 2, w1) = 0x07000000;
        GFX_AT(gfx, 2, w0) = 0xF5000100;
        cursor = gfx + 0x20;
        GFX_AT(gfx, 3, w0) = 0xE6000000;
        GFX_AT(gfx, 3, w1) = 0;
        cursor = gfx + 0x28;
