// Writes `packed`'s low 6 bits as a number and, when bits 10-14 are set, its bits 12-17 in brackets after it ('N(M)').
// From the N64 function at 0x80112B60 (28 instructions).
// Called by: number_and_bracket_text.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
P<s8> write_number_and_bracket_text(recomp_context* ctx, s32 dest, u32 packed) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x14, ctx->r31);
    s32 after_first;
    P<s8> after_second;

    after_first = lift_call<s32>(ctx, n64::format_number)(dest, packed & 0x3F, 0);
    if ((packed >> 0xA) & 0x1F) {
        M2C_FIELD(after_first, P<s8> , 0) = 0x28;
        after_second = lift_call<s32>(ctx, n64::format_number)(after_first + 1, (packed >> 0xC) & 0x3F, 0);
        *after_second = 0x29;
        after_first = (s32) (after_second + 1);
    }
    M2C_FIELD(after_first, P<s8> , 0) = 0;
    return (P<s8> ) after_first;
}

// Text record (style 7) of write_number_and_bracket_text for `packed`; '0' (0x8014A3E0) when there's no record.
// From the N64 function at 0x80112BD0 (25 instructions).
