// Writes the Japanese reign ordinal of `n`: '初代' (first) for 1, else '第' n '代' (strings 0x80154A58 / 5C / 60).
// From the N64 function at 0x80112EB4 (26 instructions).
// Called by: reign_number_text.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void write_reign_number_text(recomp_context* ctx, s32 dest, s32 n) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x14, ctx->r31);
    s32 unused;
    s32 destination;

    if (n == 1) {
        destination = lift_call<s32>(ctx, n64::copy_string)(dest, field::var::reign_first_text);
    } else {
        destination = lift_call<s32>(ctx, n64::format_number)(lift_call<s32>(ctx, n64::copy_string)(dest, field::var::reign_ordinal_prefix_text), n, 0);
    }
    unused = lift_call<s32>(ctx, n64::copy_string)(destination, field::var::reign_ordinal_suffix_text);
}

// Text record (style 0x10) of write_reign_number_text for `n`; '--' (0x80148B80) from 100 on. Caller draw_title_reign_line.
// From the N64 function at 0x80112F1C (33 instructions).
// Called by: draw_title_reign_line.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 reign_number_text(recomp_context* ctx, s32 n) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x18, ctx->r31);
    frame.keep(0x10, ctx->r16);
    s32 make_text_texture_result;
    s32 make_text_texture_result_2;
    s32 result;

    if (n != 0) {
        if (n >= 0x64) {
            return field::var::reign_number_dashes_text;
        }
        make_text_texture_result = lift_call<s32>(ctx, n64::make_text_texture)(n | 0x10000, 0x10);
        make_text_texture_result_2 = make_text_texture_result;
        if (make_text_texture_result_2 == 0) {
            return field::var::menu_empty_text;
        }
        result = make_text_texture_result_2;
        if (TEXT_RECORD(make_text_texture_result_2, string) == 0xFF) {
            lift_call<s32>(ctx, n64::write_reign_number_text)(make_text_texture_result_2, n);
            result = make_text_texture_result_2;
        }
        return result;
    }
    return field::var::menu_empty_text;
}

// Writes `value`'s high byte as a letter ('@' + n) when set, then its low byte as a number when set.
// From the N64 function at 0x80112FA0 (21 instructions).
// Called by: letter_number_text.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 write_letter_number_text(recomp_context* ctx, P<s8> dest, s32 value) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r31);
    s32 value_low_byte;
    s32 temp_v0;
    s32 var_v0;
    P<s8> temp_v1;
    P<s8> var_a0;

    var_a0 = dest;
    var_v0 = value;
    if (value < 0) {
        var_v0 = value + 0xFF;
    }
    temp_v0 = var_v0 >> 8;
    temp_v1 = var_a0;
    if (temp_v0 != 0) {
        var_a0 += 1;
        *temp_v1 = temp_v0 + 0x40;
    }
    value_low_byte = value & 0xFF;
    if (value_low_byte != 0) {
        var_a0 = lift_call<s32>(ctx, n64::format_number)((s32) var_a0, value_low_byte, 0);
    }
    return (s32) var_a0;
}

