            lift_out_a2 = 3;
block_22:
            lift_call<s32>(ctx, n64::start_animation)((s32) wrestler, var_a1, var_a2);
block_23:
            phase_2 = WRESTLER_AS(his_record, phase, u32);
            new_phase = phase_2 + 1;
            lift_out_v0 = new_phase;
            WRESTLER_AS(his_record, phase, u32) = (u32) new_phase;
            break;
        case 1:
            angle = WRESTLER(his_record, travel_angle);
            side_of_man = lift_call<s32>(ctx, n64::side_of_man)(target_record, angle);
            side_of_man_2 = side_of_man;
            WRESTLER(his_record, corner) = side_of_man_2;
            sp18 = GAME_TABLE(pin_cover_side_spot_x, ((side_of_man_2 << 0x10) >> 0xD));
            corner = WRESTLER(his_record, corner);
            copied_6334 = GAME_TABLE(pin_cover_side_spot_z, (corner * 8));
            sp1C = 0;
            sp20 = copied_6334;
            corner_2 = WRESTLER(his_record, corner);
            target_facing = WRESTLER(target_record, facing);
            corner_times_4 = corner_2 * 4;
            lift_out_v0 = corner_times_4;
            angle_2 = GAME_TABLE(side_angles, corner_times_4);
            new_wanted_facing = lift_call<s32>(ctx, n64::add_angles)(angle_2, target_facing);
            WRESTLER(his_record, wanted_facing) = new_wanted_facing;
            target_flags_8a = WRESTLER(target_record, flags_8a);
            target_flags_8a_bit0 = target_flags_8a & 1;
            lift_out_v0 = target_flags_8a_bit0;
            origin = target_record + 0xFC;
            if (target_flags_8a_bit0 != 0) {
                temp_f2 = sp20;
                sp18 = -sp18;
                sp20 = -temp_f2;
                angle_3 = WRESTLER(his_record, wanted_facing);
                WRESTLER(his_record, wanted_facing) = lift_call<s32>(ctx, n64::add_angles)(angle_3, 0x800);
                origin = target_record + 0xFC;
            }
            target_facing_2 = WRESTLER(target_record, facing);
