            phase_3 = WRESTLER_AS(his_record, phase, u32);
            new_phase_2 = phase_3 + 1;
            WRESTLER_AS(his_record, phase, u32) = (u32) new_phase_2;
            
        case 2:
            flags_80_2 = WRESTLER(his_record, flags_80);
            flags_8a_3 = WRESTLER(his_record, flags_8a);
            new_flags_80_2 = flags_80_2 | 1;
            WRESTLER(his_record, flags_80) = (u16) new_flags_80_2;
            flags_8a_bit3_2 = flags_8a_3 & 8;
            if (flags_8a_bit3_2 == 0) {
                new_flags_8a = flags_8a_3 | 0x100;
                WRESTLER(his_record, flags_8a) = (u16) new_flags_8a;
            }
            lift_out_v0 = 0xFFFFE;
            lift_out_a2 = 0x40800000;
            points3 = his_record + 0x264;
            lift_out_a3 = (s32) points3;
            lift_call<s32>(ctx, n64::push_out_of_walls_with_points)((s32) his_record, target_record, 0x40800000, (s32) points3, 0xFFFFE);
