            title_on_the_line_times_2 = (s32) GAME_VAR(title_on_the_line) * 2;
            lift_out_v0 = title_on_the_line_times_2;
            text_id = GAME_TABLE(title_label_400_text_ids, title_on_the_line_times_2);
