// Length of the 31-character name buffer `text` without its trailing spaces and zeros. Callers name_entry_page_run (the name entry's run), copy_trimmed_name.
// From the N64 function at 0x80113BA4 (14 instructions).
// Called by: name_entry_page_run, copy_trimmed_name.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 trimmed_name_length(s32 text) {
    s32 length;
    P<u8> character_at;
    u32 character;

    length = 0x1E;
    character_at = text + 0x1E;
    for (;;) {
        character = *character_at;
        if (!((character != 0) & (character != 0x20))) {
            length -= 1;
            character_at -= 1;
            if (length >= 0) {
                continue;
            }
        }
        break;
    }
    return length + 1;
}

// Copies the name buffer `text` without trailing spaces (trimmed_name_length) into `out` with a terminating zero. Caller name_entry_page_run (name entry).
// From the N64 function at 0x80113BDC (24 instructions).
// Called by: name_entry_page_run.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void copy_trimmed_name(recomp_context* ctx, P<u8> out, s32 text) {
    LiftFrame frame(ctx, 0x28);
    frame.keep(0x1C, ctx->r17);
    frame.keep(0x18, ctx->r16);
    frame.keep(0x20, ctx->r31);
    s32 trimmed_name_length;
    s32 trimmed_name_length_2;
    s32 text_now;
    s32 i;
    P<u8> out_at;
    s32 copied_0;

    out_at = out;
    text_now = text;
    trimmed_name_length = lift_call<s32>(ctx, n64::trimmed_name_length)(text_now);
    trimmed_name_length_2 = trimmed_name_length;
    i = 0;
    if (trimmed_name_length_2 > 0) {
        do {
            copied_0 = M2C_FIELD(text_now, P<u8> , 0);
            text_now += 1;
            i += 1;
            *out_at = copied_0;
            out_at += 1;
        } while (i < trimmed_name_length_2);
    }
    *out_at = 0;
}

