    WRESTLER_AS(wrestler, tag_stamina, u16) = (u16) WRESTLER_AS(wrestler, stamina, u16);
    lift_call<s32>(ctx, n64::ai_set_up_slot)((s32) slot);
    lift_call<s32>(ctx, n64::clear_hit_stats_of_model)((s32) slot);
