        lift_call<f32>(ctx, n64::gu_position_f)((s32) &sp20, 0, __builtin_bit_cast(s32, lift_plain((f32) ((f64) INTRO_MAN(man, facing) * GAME_VAR(f64_0p087890625_4)))), 0, 0x3F800000, __builtin_bit_cast(s32, lift_plain(INTRO_MAN(man, x))), __builtin_bit_cast(s32, lift_plain(INTRO_MAN(man, y))), __builtin_bit_cast(s32, lift_plain(INTRO_MAN(man, z))));
