// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void award_fall(recomp_context* ctx, P<void> loser, s32 scorer_slot) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r31);
    s32 scorer_slot_offset;
    s32 new_falls;

    scorer_slot_offset = scorer_slot * 4;
    new_falls = GAME_ARRAY(slot_falls, scorer_slot_offset) + 1;
    GAME_ARRAY(slot_falls, scorer_slot_offset) = new_falls;
    if (new_falls >= 0x64) {
        GAME_ARRAY(slot_falls, scorer_slot_offset) = 0x63;
    }
    if (loser != NULL) {
        if (M2C_FIELD(loser, P<s16> , 0xAA) < 0x3C) {
            M2C_FIELD(loser, P<s16> , 0xAA) = 0x3C;
        }
        lift_call<s32>(ctx, n64::update_spirit_meter)((s32) loser, 7);
    }
}

// The slot's falls (s32 0x8017D2F0[slot], award_fall). Read by the HUD code (update_hud_popups_and_counts, func_800E0304).
