// The scene light colour for the playing intro entry by its flags +2 >> 12 (0x1000 (0x80, 0x40, 0x40), 0x2000 (0x40, 0x80, 0x40), 0x3000 (0x20, 0x40, 0x80), ... else grey 0x80): ease_light_colour by `step`, at once when `step` < 0.
// From the N64 function at 0x80118094 (86 instructions).
// Has gotos where m2c couldn't find the loop or the if: its structure is to be tidied by hand.
// Called by: play_intro_script, start_intro_entry.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 371 comparisons, no difference (caller twin v11, 0.84, match_tag, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, rules_single_hardcore, select_wcw, smoke_singles; see the header's caller-twin note).
void set_intro_light(recomp_context* ctx, s32 step) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r31);
    s32 entry_light_kind;
    s32 red;
    s32 green;
    s32 blue;

    entry_light_kind = INTRO_ENTRY(GAME_VAR_AS(intro_entry_now, P<void>), flags) & 0xF000;
    if (entry_light_kind != 0x5000) {
        if (entry_light_kind < 0x5001) {
            if (entry_light_kind != 0x2000) {
                if (entry_light_kind < 0x2001) {
                    red = 0x80;
                    if (entry_light_kind != 0x1000) {
                        green = 0x80;
                        goto block_27;
                    }
                    green = 0x40;
                    blue = 0x40;
                } else {
                    if (entry_light_kind != 0x3000) {
                        red = 0x60;
                        if (entry_light_kind != 0x4000) {
                            red = 0x80;
                            goto block_26;
                        }
                        green = 0x20;
                    } else {
                        red = 0x20;
                        green = 0x40;
                    }
                    goto block_27;
                }
            } else {
                red = 0x40;
                green = 0x80;
                blue = 0x40;
            }
            goto block_28;
        }
        if (entry_light_kind != 0x8000) {
            if (entry_light_kind <= 0x8000) {
                if (entry_light_kind != 0x6000) {
                    red = 0x60;
                    if (entry_light_kind != 0x7000) {
                        red = 0x80;
                        goto block_26;
                    }
                    green = 0x20;
                    blue = 0x20;
                } else {
                    red = 0x80;
                    green = 0x60;
                    blue = 0x40;
                }
                goto block_28;
            }
            if (entry_light_kind != 0x9000) {
                red = 0x80;
                if (entry_light_kind != 0xF000) {
                    goto block_26;
                }
            } else {
                red = 0x60;
                green = 0x60;
                blue = 0x60;
                goto block_28;
            }
        } else {
            blue = 0x80;
            red = 0x60;
            green = 0x60;
            goto block_28;
        }
    } else {
        red = 0x40;
block_26:
        green = 0x80;
block_27:
        blue = 0x80;
block_28:
        if (step < 0) {
            red = -red;
            green = -green;
            blue = -blue;
        }
        lift_call<s32>(ctx, n64::ease_light_colour)(red, green, blue, step);
    }
}

