// With match flag 0x04000000: the slot's +0xF9 - +0xF8, less 1 when he is not taking part (+0xE9 bit 4); otherwise 0x80159210 - 0x80159214 plus the men taking part now. Read by the HUD code (0x800E0790); reading: the men still to come / left in an elimination match or the Rumble. (2026-11-12, names4: confirmed from the lifted C++: the name says only what the code does).
// From the N64 function at 0x80119258 (52 instructions).
// Called by: update_hud_popups_and_counts.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 men_left_to_enter_count(recomp_context* ctx, s32 slot) {
    s32 count_in_gp;
    s32 slot_offset;
    s32 men_left;
    s32 i;
    s32 offset;

    count_in_gp = ((s32)ctx->r28);
    if ((s32) GAME_VAR(match_flags) & 0x04000000) {
        slot_offset = slot * 0x358;
        return (GAME_TABLE_AS(wrestler_0_team_entrant_end, slot_offset, u8) - WRESTLER_IN(wrestlers, slot_offset, rumble_index)) - ((WRESTLER_IN(wrestlers, slot_offset, control_flags) & 0x10) == 0);
    }
    men_left = 0;
    i = 0;
    offset = 0;
    do {
        i += 1;
        if (WRESTLER_IN_AS(wrestlers, offset, superstar, s16) != -1) {
            men_left += (WRESTLER_IN(wrestlers, offset, control_flags) & 0x10) != 0;
        }
        offset += 0x358;
    } while (i < count_in_gp);
    return (GAME_VAR(rumble_entrant_count) - GAME_VAR(rumble_next_entrant)) + men_left;
}

