// Intro set value `set`: the stage from the u16 table 0x80130410[set & 0x7F] (& 0x7F, 0x80 -> ring flag 0x80097EC0 = 0x10000) through set_scene_stage when it changed (0x8014B6B0); 0x8014B6AC = set; unless set & 0x8000 also place_intro_set_object((set >> 8) & 3) and start_stage_effect(0x80130468[(set >> 12) & 3]); 0x80106614 = 0 outside 0x800A10B0 & 4.
// From the N64 function at 0x8011ABF0 (51 instructions).
// Called by: start_intro_entry, run_intro_frame.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 187 comparisons, no difference (caller twin v11, 0.84, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, select_wcw; see the header's caller-twin note).
void set_intro_set(recomp_context* ctx, u32 set) {
    LiftFrame frame(ctx, 0x18);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x14, ctx->r31);
    s32 unused;
    s32 unused_2;
    s32 entry_low_half;
    s32 entry;

    entry = GAME_TABLE(intro_set_stages, ((set & 0x7F) * 2));
    entry_low_half = entry & 0xFFFF;
    if (GAME_VAR(intro_set_stage) != entry_low_half) {
        GAME_VAR(intro_set_stage) = entry_low_half;
        if (entry_low_half != 0) {
            if (entry & 0x80) {
                GAME_VAR(match_flags) = 0x10000;
            } else {
                GAME_VAR(match_flags) = 0;
            }
        }
        lift_call<s32>(ctx, n64::set_scene_stage)(entry & 0x7F);
    }
    GAME_VAR_AS(intro_set_now, u32) = set;
    if (!(set & 0x8000)) {
        unused = lift_call<s32>(ctx, n64::place_intro_set_object)((set >> 8) & 3);
        unused_2 = lift_call<s32>(ctx, n64::start_stage_effect)((s32) GAME_TABLE(intro_set_stage_effects, ((set >> 0xC) & 3)));
        if (!(GAME_VAR(game_loop_route_flags) & 4)) {
            GAME_VAR(intro_set) = 0;
        }
    }
}

