// Sprite `sprite` (0x10 bytes: +0 display list, +4 vertices, +8 their count) frame `frame_index` at *`list`: its list, its vertices, and for frames below 0x1C its texture (load_effect_sprite_texture) and the quad (0x07000206 / 0x604).
// From the N64 function at 0x8011C274 (46 instructions).
// Called by: draw_burst_sprite_frame, draw_effect_burst.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 312 comparisons, no difference (caller twin v11, 0.84, menu_from_attract, modes_reg_rumble (match not reached), modes_regular_boot, select_wcw; see the header's caller-twin note).
void draw_effect_sprite_frame(recomp_context* ctx, P<P<void>> list, u32 frame_index, P<void> sprite) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x18, ctx->r16);
    frame.keep(0x1C, ctx->r31);
    Ref<P<void>> cursor(frame.at(0x10));
    s32 load_effect_sprite_texture_result;
    s32 sprite_word_4;
    s32 sprite_half_8;
    P<void> gfx;
    P<void> gfx_2;
    P<void> gfx_3;

    gfx = *list;
    GFX(gfx, w0) = 0xDE000000;
    GFX(gfx, w1) = (s32) M2C_FIELD(sprite, P<s32> , 0);
    sprite_half_8 = M2C_FIELD(sprite, P<u16> , 8);
    GFX_AT(gfx, 1, w0) = (s32) (((sprite_half_8 & 0xFF) << 0xC) | (((sprite_half_8 & 0x7F) * 2) | 0x01000000));
    sprite_word_4 = M2C_FIELD(sprite, P<s32> , 4);
    cursor = gfx + 8;
    cursor = gfx + 0x10;
    GFX_AT(gfx, 1, w1) = sprite_word_4;
    if (frame_index < 0x1CU) {
        load_effect_sprite_texture_result = lift_call<s32>(ctx, n64::load_effect_sprite_texture)((s32) &cursor, (s32) sprite, (s32) frame_index);
        if (load_effect_sprite_texture_result != 0) {
            gfx_3 = cursor;
            cursor = gfx_3 + 8;
            GFX(gfx_3, w0) = 0x07000206;
            GFX(gfx_3, w1) = 0x604;
        }
    }
    gfx_2 = cursor;
    *list = gfx_2;
}

