// Builds one row of the part editor's option list (ovl_d page 15) in widget `widget` of pool 2: option `row` of the part being edited (part_option_entry with the part 0x80150414, its group 0x80150418 and 0x8015041F, over the editor's unlocked list +0x4DC / +0x4E0), its name formatted (format_string (func_80036AD0), format 0x8014BDC4) as a text widget (widget + 6) over a 0x50 x 0xE bar picture (files 0x4A12 / 0x4A11); returns its unlock state (item_unlock_state(4, page 0x8015031C - 4, option id)). Called through the list's row-builder pointer; no direct callers. (2026-11-13, names5: confirmed: part_option_entry (confirmed) gives the row's entry, made into the row's widgets of pool 2).
// From the N64 function at 0x8011C328 (76 instructions).
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void build_part_option_row(recomp_context* ctx, s32 widget, s32 row, P<void> editor) {
    LiftFrame frame(ctx, 0x88);
    frame.keep(0x78, ctx->r18);
    frame.keep(0x80, ctx->r31);
    frame.keep(0x7C, ctx->r19);
    frame.keep(0x74, ctx->r17);
    frame.keep(0x70, ctx->r16);
    LiftAbiOut lift_out_a2{ctx->r6};   // the context's a2, kept in step with the original's
    LiftAbiOut lift_out_a3{ctx->r7};   // the context's a3, kept in step with the original's
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    Ref<u8> entry(frame.at(0x30));
    Ref<M2C_UNK> entry_name(frame.at(0x32));
    Ref<M2C_UNK> text(frame.at(0x50));
    s32 part;
    s32 n;
    s32 page_kind;
    s32 unused;
    s32 unlock_state;
    s32 editor_word_4dc;
    u32 entry_2;
    s32 byte_8015041f;

    lift_out_v0 = (s32) &entry;
    editor_word_4dc = M2C_FIELD(editor, P<s32> , 0x4DC);
    lift_out_v0 = editor_word_4dc;
    lift_out_a2 = row;
    part = GAME_VAR(part_option_rows_part);
    n = GAME_VAR(part_option_rows_group);
    lift_out_a3 = field::var::hi(field::var::part_edit_body_option_kind_low);
    byte_8015041f = GAME_VAR(part_edit_body_option_kind_low);
    lift_out_a3 = (s32) byte_8015041f;
    lift_call<s32>(ctx, n64::part_option_entry)(part, n, row, (s32) byte_8015041f, (s32) &entry, editor_word_4dc, (s32) (editor + 0x4E0));
    lift_out_a2 = (s32) &entry_name;
    lift_call<s32>(ctx, n64::format_string)((s32) &text, field::var::text_pct_s, (s32) &entry_name);
    lift_out_a2 = 0;
    lift_out_a3 = 0;
    lift_out_v0 = 0x4A11;
    lift_call<s32>(ctx, n64::make_picture_widget)(2, widget, 0, 0, 0x50, 0xE, 0x4A12, 0x4A11, -1, -1, 0);
    lift_out_a2 = 0;
    lift_out_a3 = 0;
    lift_out_v0 = 5;
    unused = lift_call<s32>(ctx, n64::make_text_widget)(2, widget + 6, 0, 0, 0xA, 0xE, (s32) &text, 5, widget, -1);
    page_kind = GAME_VAR(page_kind);
    entry_2 = entry;
    lift_out_a2 = (s32) entry_2;
    unlock_state = lift_call<s32>(ctx, lift_lookup<0x800D9AB0u>)(4, (s32) (s16) (page_kind - 4), (s32) entry_2);
    lift_out_v0 = (unlock_state & 0xFF) == 1;
}

