    Ref<s32> sp2C(frame.at(0x2C));
    Ref<s32> sp30(frame.at(0x30));
    Ref<s32> sp38(frame.at(0x38));
    Ref<s32> sp3C(frame.at(0x3C));
    Ref<s32> sp40(frame.at(0x40));
    Ref<s32> sp48(frame.at(0x48));
    Ref<s32> sp4C(frame.at(0x4C));
    Ref<s32> sp50(frame.at(0x50));
    Ref<M2C_UNK> sp58(frame.at(0x58));
    Ref<M2C_UNK> sp98(frame.at(0x98));
    f32 temp_f2;
    f32 unused;
    f32 unused_2;
    f32 sine;
    f32 cosine;
    s32 source;

    if (alternate != 0) {
        source = (bone * 0x7C) + field::var::slot_bone_top_point;
    } else {
        source = GAME_TABLE(model_slot_bone_draw_objects, (bone * 0xDC)) + 0xC;
    }
    lift_call<s32>(ctx, n64::copy_memory)(source, (s32) &sp28, 0xC);
    lift_call<f32>(ctx, n64::read_camera_eye)((s32) &sp38, (s32) &sp3C, (s32) &sp40);
    unused = lift_call<f32>(ctx, n64::read_camera_target)((s32) &sp48, (s32) &sp4C, (s32) &sp50);
    lift_call<f32>(ctx, n64::gu_look_at_f)((s32) &sp58, sp38, sp3C, sp40, sp48, sp4C, sp50, 0, 0x3F800000, 0);
    unused_2 = lift_call<f32>(ctx, n64::multiply_matrices)((bone * 0xDC) + field::var::model_slot_bone_matrices, (s32) &sp58, (s32) &sp98);
