// fill_quad_vertices with all four vertices in colour (r, g, b, a).
// From the N64 function at 0x8011C49C (34 instructions).
// Called by: draw_coloured_quad.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void fill_coloured_quad_vertices(P<void> vtx, s32 arg1, s32 arg2, s32 arg3, u16 arg4, u8 r, u8 g, u8 b, u8 a) {
    VERTEX_AT(vtx, 3, r) = r;
    VERTEX_AT(vtx, 2, r) = r;
    VERTEX_AT(vtx, 1, r) = r;
    VERTEX(vtx, r) = r;
    VERTEX_AT(vtx, 3, g) = g;
    VERTEX_AT(vtx, 2, g) = g;
    VERTEX_AT(vtx, 1, g) = g;
    VERTEX(vtx, g) = g;
    VERTEX_AT(vtx, 3, b) = b;
    VERTEX_AT(vtx, 2, b) = b;
    VERTEX_AT(vtx, 1, b) = b;
    VERTEX(vtx, b) = b;
    VERTEX_AT(vtx, 2, x) = arg1;
    VERTEX(vtx, x) = arg1;
    VERTEX_AT(vtx, 3, x) = arg3;
    VERTEX_AT(vtx, 1, x) = arg3;
    VERTEX_AT(vtx, 1, y) = arg2;
    VERTEX(vtx, y) = arg2;
    VERTEX_AT(vtx, 3, z) = 0;
    VERTEX_AT(vtx, 2, z) = 0;
    VERTEX_AT(vtx, 1, z) = 0;
    VERTEX(vtx, z) = 0;
    VERTEX_AT_AS(vtx, 3, y, u16) = arg4;
    VERTEX_AT_AS(vtx, 2, y, u16) = arg4;
    VERTEX_AT(vtx, 3, a) = a;
    VERTEX_AT(vtx, 2, a) = a;
    VERTEX_AT(vtx, 1, a) = a;
    VERTEX(vtx, a) = a;
}

