    frame.keep(0x1C, ctx->r31);
    frame.keep(0x18, ctx->r18);
    frame.keep(0x10, ctx->r16);
    LiftAbiKeep lift_keep_s2(ctx->r18);   // s2 goes back as it came in
    LiftAbiOut lift_out_s2{ctx->r18};   // the context's s2, kept in step with the original's
    s32 temp_a0_2;
    s32 effect_frame_texture;
    s32 texture;
    s32 temp_v0_4;
    s32 temp_v0_6;
    s32 temp_v1;
    s32 var_a1;
    s32 var_a2;
    s32 var_v0;
    s32 var_v1;
    s32 var_v1_2;
    s32 sprite_half_a;
    P<void> gfx;
    P<void> gfx_2;
    P<void> gfx_3;
    P<void> gfx_4;
    P<void> gfx_5;
    P<void> gfx_6;
    P<void> gfx_7;
    P<void> sprite;
    P<void> sprite_2;
    P<void> sprite_3;
    P<void> sprite_4;
    P<void> sprite_5;
    P<void> cursor;

    sprite = EFFECT_RECORD(record, sprite);
    lift_out_s2 = list;
    sprite_half_a = M2C_FIELD(sprite, P<u16> , 0xA);
    cursor = GFX_CURSOR(list, next);
