        GFX_AT(gfx, 1, w0) = 0xE6000000;
        GFX(gfx_2, w1) = 0;
        GFX_AT(gfx_2, 1, w0) = 0xF3000000;
        gfx_4 = gfx_3 + 8;
        temp_v0_4 = 1 << (M2C_FIELD(EFFECT_RECORD(record, sprite), P<u8> , 0xD) & 31);
        var_v1 = temp_v0_4;
        if (temp_v0_4 < 0) {
            var_v1 = temp_v0_4 + 0xF;
        }
        temp_v1 = var_v1 >> 4;
        var_a2 = 0x800;
        if (temp_v1 > 0) {
            var_a2 = temp_v1 + 0x7FF;
        }
        sprite_3 = EFFECT_RECORD(record, sprite);
        temp_a0_2 = 1 << (M2C_FIELD(sprite_3, P<u8> , 0xD) & 31);
        var_v1_2 = ((s32) ((temp_a0_2 << (M2C_FIELD(sprite_3, P<u8> , 0xE) & 31)) + 3) >> 2) - 1;
