// The spirit meter's routine for `wrestler`, by `mode` (his spirit +0xAE, the meter bits +0xEE: 1 DANGER, 2 SPECIAL lit, 4 SPECIAL ready; the timer +0xB0); returns 1 only from mode 5:
// 0: timer = 120.
// 1 (each step; nothing with a meter bit set or on the cage wall): every 120 steps his spirit drifts -- by -8 (kept at 1) when he is off the ring and apron (+0x82 & 3) while his target (+0x08) is on one, else toward 50 (51 and up -1, 31-49 +2, 30 and below +3).
// 2 (each step with a meter bit set): counts the timer down; when it runs out the spirit is set by the bit (DANGER 40, SPECIAL lit 70, SPECIAL ready 60), and then -- or at once while SPECIAL is lit with spirit under 100 -- the timer goes back to 120 and the meter bits are cleared.
// 3 (apply_move_damage, on the man hit): with SPECIAL lit or ready the timer loses 60.
// 4: DANGER: timer 300, spirit 0, bits 1.
// 5: with SPECIAL lit, makes it ready: timer 600, bits 4, returns 1.
// 7: spirit 50 and the meter ended (timer 120, bits 0). Other modes do nothing.
// Called by the step driver, standing (1), the taunts (27, 28), set_up_wrestler_slot and others (12 callers). (2026-11-12: renamed from tick_spirit_drift, which is only mode 1; every mode read from the code.)
// From the N64 function at 0x8011D100 (138 instructions).
// Called by: run_wrestler_state_step, wrestler_state_1_standing, wrestler_state_27_taunt, wrestler_state_28_taunt_with_man and 8 more.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 7692 comparisons, no difference (leaf twin, 0.84, match_tag, menu_from_attract, rules_single_hardcore, smoke_singles).
s32 update_spirit_meter(P<void> wrestler, u32 mode) {
    s32 spirit;
    u32 special_timer_minus_1;
    s32 area_bits;
    u32 spirit_minus_8;
    u32 special_timer_minus_1_2;

    switch (mode) {
    case 0:
        WRESTLER_AS(wrestler, special_timer, u16) = 0x78U;
    default:
        return 0;
    case 1:
        if (!(WRESTLER(wrestler, meter_flags) & 7) && !(WRESTLER(wrestler, area_bits) & 0x400)) {
            special_timer_minus_1 = WRESTLER_AS(wrestler, special_timer, u16) - 1;
            WRESTLER_AS(wrestler, special_timer, u16) = special_timer_minus_1;
            if ((s32) (special_timer_minus_1 << 0x10) <= 0) {
                area_bits = WRESTLER(wrestler, area_bits);
                WRESTLER_AS(wrestler, special_timer, u16) = 0x78U;
                if (!(area_bits & 3) && (WRESTLER_IN(wrestlers, (WRESTLER(wrestler, target_slot) * 0x358), area_bits) & 3)) {
                    spirit_minus_8 = WRESTLER_AS(wrestler, spirit, u16) - 8;
                    WRESTLER_AS(wrestler, spirit, u16) = spirit_minus_8;
                    if ((s32) (spirit_minus_8 << 0x10) <= 0) {
                        WRESTLER_AS(wrestler, spirit, u16) = 1U;
                    }
                } else {
                    spirit = (s16) WRESTLER(wrestler, spirit);
                    if (spirit >= 0x33) {
                        WRESTLER_AS(wrestler, spirit, u16) = (u16) (spirit - 1);
                    } else if (spirit != 0x32) {
                        if (spirit >= 0x1F) {
                            WRESTLER_AS(wrestler, spirit, u16) = (u16) (spirit + 2);
                        } else {
                            WRESTLER_AS(wrestler, spirit, u16) = (u16) (spirit + 3);
                        }
                    }
                }
            }
        }
        
        return 0;
    case 2:
        if (WRESTLER(wrestler, meter_flags) & 7) {
            special_timer_minus_1_2 = WRESTLER_AS(wrestler, special_timer, u16) - 1;
            WRESTLER_AS(wrestler, special_timer, u16) = special_timer_minus_1_2;
            if ((s32) (special_timer_minus_1_2 << 0x10) <= 0) {
                if (WRESTLER(wrestler, meter_flags) & 1) {
                    WRESTLER_AS(wrestler, spirit, u16) = 0x28U;
                }
                if (WRESTLER(wrestler, meter_flags) & 2) {
                    WRESTLER_AS(wrestler, spirit, u16) = 0x46U;
                }
                if (WRESTLER(wrestler, meter_flags) & 4) {
                    WRESTLER_AS(wrestler, spirit, u16) = 0x3CU;
                }
                WRESTLER_AS(wrestler, special_timer, u16) = 0x78U;
                WRESTLER(wrestler, meter_flags) = 0U;
                return 0;
            }
            if ((WRESTLER(wrestler, meter_flags) & 2) && ((s16) WRESTLER(wrestler, spirit) < 0x64)) {
                WRESTLER_AS(wrestler, special_timer, u16) = 0x78U;
                WRESTLER(wrestler, meter_flags) = 0U;
            }
        }
        
        return 0;
    case 3:
        if (WRESTLER(wrestler, meter_flags) & 6) {
            WRESTLER_AS(wrestler, special_timer, u16) = (u16) (WRESTLER_AS(wrestler, special_timer, u16) - 0x3C);
        }
        
        return 0;
    case 4:
        WRESTLER_AS(wrestler, special_timer, u16) = 0x12CU;
        WRESTLER_AS(wrestler, spirit, u16) = 0U;
        WRESTLER(wrestler, meter_flags) = 1U;
        return 0;
    case 5:
        if (WRESTLER(wrestler, meter_flags) & 2) {
            WRESTLER_AS(wrestler, special_timer, u16) = 0x258U;
            WRESTLER(wrestler, meter_flags) = 4U;
            return 1;
        }
        return 0;
    case 7:
        WRESTLER_AS(wrestler, spirit, u16) = 0x32U;
        WRESTLER_AS(wrestler, special_timer, u16) = 0x78U;
        WRESTLER(wrestler, meter_flags) = 0U;
        return 0;
    }
}

