void clear_run_in_bit_f1_2(P<void> wrestler) {
    s32 run_in_bits;
    s32 control_flags;

    control_flags = WRESTLER(wrestler, control_flags);
    if (control_flags & 2) {
        run_in_bits = WRESTLER(wrestler, run_in_bits);
        if ((run_in_bits & 2) && (WRESTLER(wrestler, stamina_max) < 0xF9) && (!(GAME_VAR(match_flags) & 0x400000) || (control_flags & 8))) {
            WRESTLER(wrestler, run_in_bits) = (u8) (run_in_bits & 0xFD);
        }
    }
}

