void draw_number_caption_row(recomp_context* ctx, P<s32> display_list, P<void> row) {
    LiftFrame frame(ctx, 0x48);
    frame.keep(0x3C, ctx->r19);
    frame.keep(0x34, ctx->r17);
    frame.keep(0x40, ctx->r31);
    frame.keep(0x38, ctx->r18);
    frame.keep(0x30, ctx->r16);
    Ref<s32> sp18(frame.at(0x18));
    Ref<s32> sp1C(frame.at(0x1C));
    Ref<s32> sp20(frame.at(0x20));
    Ref<s32> sp24(frame.at(0x24));
    Ref<s32> gfx(frame.at(0x28));
    s32 list_top;
    s32 unused;
    s32 picture;
    s32 picture_2;
    s32 picture_3;
    s32 picture_4;
    s32 gfx_2;

    list_top = MENU_ROW(row, list_top);
    gfx = *display_list;
    if (list_top == 1) {
        lift_call<s32>(ctx, n64::draw_framed_box)((s32) &gfx, 0x810A, 0, (s32) GAME_VAR(wobble_counter), 0, 0);
    }
    unused = lift_call<s32>(ctx, n64::load_shared_palette)((s32) &gfx);
    picture = lift_call<s32>(ctx, n64::text_id_picture)((-((MENU_ROW(row, label) & 0x80) != 0) & 0xF109) | 0xF108, 0x30);
    picture_3 = picture;
    if (picture_3 != 0) {
        sp18 = (s32) ROW_STYLE_POINT_AT(ROW_STYLE_AS(MENU_ROW(row, style), points, P<s16>), 2, x);
        sp20 = (s32) ROW_STYLE_POINT_AT(ROW_STYLE_AS(MENU_ROW(row, style), points, P<s16>), 2, y);
        sp1C = (s32) ROW_STYLE_POINT_AT(ROW_STYLE_AS(MENU_ROW(row, style), points, P<s16>), 3, x);
        sp24 = (s32) ROW_STYLE_POINT_AT(ROW_STYLE_AS(MENU_ROW(row, style), points, P<s16>), 3, y);
        lift_call<s32>(ctx, n64::draw_menu_picture_in_span)((s32) &gfx, picture_3, (s32) &sp18, (s32) &sp20, 0, lift_call<s32>(ctx, n64::narrow_span_to_width)(picture_3, (s32) &sp18, 0x40));
    }
    picture_2 = lift_call<s32>(ctx, n64::text_id_picture)((MENU_ROW(row, label) & 0xF) + 0xF105, 0x20);
    picture_4 = picture_2;
    if (picture_4 != 0) {
        sp18 = (s32) ROW_STYLE_POINT(ROW_STYLE_AS(MENU_ROW(row, style), points, P<s16>), x);
        sp20 = (s32) ROW_STYLE_POINT(ROW_STYLE_AS(MENU_ROW(row, style), points, P<s16>), y);
        sp1C = (s32) ROW_STYLE_POINT_AT(ROW_STYLE_AS(MENU_ROW(row, style), points, P<s16>), 1, x);
        sp24 = (s32) ROW_STYLE_POINT_AT(ROW_STYLE_AS(MENU_ROW(row, style), points, P<s16>), 1, y);
        lift_call<s32>(ctx, n64::draw_menu_picture_in_span)((s32) &gfx, picture_4, (s32) &sp18, (s32) &sp20, 0, lift_call<s32>(ctx, n64::narrow_span_to_width)(picture_4, (s32) &sp18, 0x40));
    }
    gfx_2 = gfx;
    *display_list = gfx_2;
}

