// 1 when the wrestler is at the ropes with them square at his back: the ropes' direction (from his rope record at +0x348) against his facing (+0x10C), within a margin on the side his +0x74 bit 25 says. The mod calls it as GF_ROPES_TEST (mod/src/arcade.h).
// From the N64 function at 0x801202F4 (41 instructions).
// Called by: wrestler_state_53_staggering_back, running_wall_step, wrestler_state_45_hit_reaction, running_wall_step_mod_copy.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 49 comparisons, no difference (caller twin v11, 0.84, match_tag, menu_from_attract, rules_single_hardcore, smoke_singles; see the header's caller-twin note).
s32 at_ropes_back_square(recomp_context* ctx, P<void> wrestler) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x18, ctx->r31);
    frame.keep(0x14, ctx->r17);
    s32 add_angles_result;
    s32 magnitude;
    s32 angle_quadrant;
    s32 add_angles_result_2;
    s32 magnitude_2;
    u32 hit_flags_high;
    P<void> nearest_wall;

    nearest_wall = WRESTLER(wrestler, nearest_wall);
    add_angles_result = lift_call<s32>(ctx, n64::add_angles)(lift_call<s32>(ctx, n64::angle_of_vector)(WALL_RECORD(nearest_wall, normal_x), WALL_RECORD(nearest_wall, normal_z)), 0x800);
    add_angles_result_2 = add_angles_result;
    magnitude = lift_call<s32>(ctx, n64::int_abs)(lift_call<s32>(ctx, n64::angle_difference)(add_angles_result_2, WRESTLER(wrestler, facing)));
    magnitude_2 = magnitude;
    hit_flags_high = (u32) WRESTLER_AS(wrestler, hit_flags, u32) >> 0x19;
    if ((!(hit_flags_high & 1 & (magnitude_2 < 0xE3))) && (!((hit_flags_high ^ 1) & 1 & (magnitude_2 >= 0x71D)))) {
        return 0;
    }
    angle_quadrant = lift_call<s32>(ctx, n64::angle_quadrant)(add_angles_result_2);
    WRESTLER(wrestler, corner) = angle_quadrant;
    return 1;
}

// 1 for a man with +0xE9 bits 0 / 1 (held below SPECIAL, a run-in), one out of the match (+0x94 bit 0), or when rule 0x400 is off; 0 otherwise. Used by try_running_through_ropes, try_c_up_at_ropes and func_8011E748.
// From the N64 function at 0x80120398 (14 instructions).
// Called by: try_running_through_ropes, wrestler_state_110_go_through_ropes, try_c_up_at_ropes, wrestler_state_110_go_through_ropes_mod_copy.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 12 comparisons, no difference (leaf twin, 0.84, match_tag, menu_from_attract, rules_single_hardcore, smoke_singles).
s32 exempt_from_rule_400(P<void> wrestler) {
    s32 result;

    result = 1;
    if (!(WRESTLER(wrestler, control_flags) & 3)) {
        result = 1;
        if (!(WRESTLER(wrestler, match_flags) & 1)) {
            result = (GAME_VAR(match_rules) & 0x400) == 0;
        }
    }
    return result;
}

// Picking step of the Superstar select in mode 3, Create a Superstar (edit_kind_page_run), with the yes / no dialog (run_page_dialog): yes (3) -> 0x80150620 = 1, no (4) -> 0; state 2 makes a new Superstar (new_superstar_defaults; +0xCC6 = 2) and goes to page 4 (the editor's main page); state 1 highlights the box (select_cursor_glide, select_box_highlight) and waits 15 frames.
// From the N64 function at 0x801203C0 (100 instructions).
// Called by: func_8011F40C.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void select_pick_new_superstar(recomp_context* ctx, s32 editor) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x1C, ctx->r31);
    frame.keep(0x18, ctx->r18);
    frame.keep(0x14, ctx->r17);
    LiftAbiOut lift_out_a2{ctx->r6};   // the context's a2, kept in step with the original's
    LiftAbiOut lift_out_a3{ctx->r7};   // the context's a3, kept in step with the original's
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    s32 box;
    s32 run_page_dialog_result;
    s32 unused;
    s32 unused_2;
    s32 select_confirmed;
    s32 editor_page;
    s32 page;
    s32 pressed_bit14;
    s32 superstar_bit15;
    s32 page_2;
    s32 run_page_dialog_result_low_byte;
    s32 back_page;
    s32 pressed;
    s32 half;

    run_page_dialog_result = lift_call<s32>(ctx, n64::run_page_dialog)(editor);
    run_page_dialog_result_low_byte = run_page_dialog_result & 0xFF;
    if (run_page_dialog_result_low_byte == 1) {
        lift_out_v0 = 0;
    } else {
        if (run_page_dialog_result_low_byte == 3) {
            GAME_VAR(select_confirmed) = 1;
        }
        if (run_page_dialog_result_low_byte == 4) {
            GAME_VAR(select_confirmed) = 0;
        }
        lift_out_v0 = field::var::hi(field::var::select_confirmed);
        select_confirmed = GAME_VAR(select_confirmed);
        lift_out_v0 = select_confirmed;
        if (select_confirmed == 2) {
            editor_page = editor + 0x70;
            lift_out_v0 = editor_page;
            GAME_VAR(superstar_select_next_page) = editor_page;
            GAME_VAR(superstar_select_back_page) = 0;
            GAME_VAR(superstar_select_step) = 3;
            lift_call<s32>(ctx, n64::new_superstar_defaults)(editor);
            lift_out_v0 = 0;
            EDITOR_STATE(editor, edit_source) = 2;
        } else if (select_confirmed == 1) {
            unused = lift_call<s32>(ctx, n64::select_cursor_glide)(0);
            page = EDITOR_STATE_AS(editor, page, s32);
            lift_out_v0 = page;
            half = GAME_VAR(select_box_half);
            box = EDITOR_PAGE(page, cursor);
            lift_out_a2 = 0;
            lift_out_a3 = -1;
            lift_call<s32>(ctx, n64::select_box_highlight)(box, (s32) half, 0, -1);
            GAME_VAR(page_input_delay) = 0xF;
            lift_out_v0 = 1;
            GAME_VAR(select_pick_made) = 1;
            lift_call<s32>(ctx, n64::play_menu_sound_panned)(0x402, 0x80);
            GAME_VAR(select_confirmed) = 2;
            lift_out_v0 = 0;
        } else {
            pressed = EDITOR_STATE(editor, pressed);
            pressed_bit14 = pressed & 0x4000;
            if ((pressed & 0x8000) != 0) {
                superstar_bit15 = (s32) EDITOR_STATE(editor, superstar) & 0x8000;
                lift_out_v0 = superstar_bit15;
                if (superstar_bit15 == 0) {
                    lift_call<s32>(ctx, n64::show_page_dialog)(8, 2);
                } else {
                    GAME_VAR(select_confirmed) = 1;
                }
                lift_out_v0 = 0;
            } else {
                lift_out_v0 = pressed_bit14;
                if (pressed_bit14 == 0) {
                    lift_out_v0 = 1;
                } else {
                    unused_2 = lift_call<s32>(ctx, n64::play_menu_sound_panned)(0x403, 0x80);
                    page_2 = EDITOR_STATE_AS(editor, page, s32);
                    back_page = EDITOR_PAGE(page_2, back_page);
                    GAME_VAR(superstar_select_next_page) = 0;
                    GAME_VAR(superstar_select_step) = 3;
                    lift_out_v0 = 0;
                    GAME_VAR(superstar_select_back_page) = back_page;
                }
            }
        }
    }
}

// Whether the match type lets this man into the ring now: a three-way / 0x4000 match (0x80097EC0 & 0xC000) needs his +0xE9 & 0x14 (taking part, or a tag-team man); with 0x21000 (handicap 0x20000, or 0x1000) it counts the others in play marked (+0xE9 bit 4 with +0x82 & 4, or +0xE9 bit 1 with +0xF1 bit 1) and checks his +0xE9 bits 0 / 1, +0xF1 bit 1 and +0x96 & 0xC0; in a tag match a man not taking part on the floor (or running) asks tag_man_entry_check (func_80138BE0). Used by wrestler_state_1_standing (a man with +0xE9 & 3 refused is turned back), try_c_up_at_ropes (C-up at the ropes from the apron: refused in a tag match -> try_tag_corner_wait), try_running_through_ropes (func_80110A90). (2026-11-12, names3: confirmed from the lifted C++: the match type bits at 0x80097EC0 & 0xC000 / 0x21000 and the count over the records' +0xE9 / +0x82 / +0xF1 as described.)
