// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void two_column_line_places(P<void> origins, P<void> x, P<void> y, s32 line, s32 flags) {
    s32 line_y;
    s32 line_y_2;

    M2C_FIELD(x, P<s32> , 0) = (s32) M2C_FIELD(origins, P<s16> , 0);
    M2C_FIELD(x, P<s32> , 4) = (s32) M2C_FIELD(origins, P<s16> , 0x18);
    if (flags & 0x80) {
        line_y = (((line % 7) * 2) + 2) * 7;
        M2C_FIELD(y, P<s32> , 0) = (s32) (M2C_FIELD(origins, P<s16> , 2) + line_y);
        M2C_FIELD(y, P<s32> , 4) = (s32) (M2C_FIELD(origins, P<s16> , 0x1A) + line_y);
        if (line >= 7) {
            M2C_FIELD(x, P<s32> , 0) = 0;
            return;
        }
        M2C_FIELD(x, P<s32> , 4) = 0;
        return;
    }
    line_y_2 = ((line * 2) + 2) * 7;
    M2C_FIELD(y, P<s32> , 0) = (s32) (M2C_FIELD(origins, P<s16> , 2) + line_y_2);
    M2C_FIELD(y, P<s32> , 4) = (s32) (M2C_FIELD(origins, P<s16> , 0x1A) + line_y_2);
}

