    s32 new_flags_8a;
    s32 angle_to_2;
    s32 magnitude_below_1024;
    s32 new_flags_8a_2;
    s32 new_flags_8a_3;
    s32 flags_8a;
    s32 flags_8a_2;
    s32 flags_8a_3;

