        sp1C = (s32) M2C_FIELD(arg2, P<s16> , 8);
        sp24 = (s32) M2C_FIELD(arg2, P<s16> , 0xA);
        var_s1 = M2C_FIELD(arg2, P<s16> , 0xC);
