// Mode 0 sets the slot's timer 0x8017D370[slot] to 60; mode 1 counts it down and clears his +0xE3 when it runs out. Called by the step driver and apply_strike_to_target (func_80121330).
// From the N64 function at 0x80122AB0 (26 instructions).
// Called by: run_wrestler_state_step, apply_strike_to_target.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 8084 comparisons, no difference (leaf twin, 0.84, match_tag, menu_from_attract, rules_single_hardcore, smoke_singles).
void tick_e3_timer(P<void> wrestler, s32 mode) {
    s32 slot;
    s32 slot_offset;
    s32 e3_timers_entry;

    if (mode != 0) {
        if (mode != 1) {
            return;
        }
        slot = WRESTLER(wrestler, slot);
        slot_offset = slot * 4;
        e3_timers_entry = GAME_ARRAY(e3_timers, slot_offset);
        if (e3_timers_entry <= 0) {
            WRESTLER(wrestler, timed_flag) = 0;
            return;
        }
        GAME_ARRAY(e3_timers, slot_offset) = (s32) (e3_timers_entry - 1);
        return;
    }
    GAME_TABLE(e3_timers, (WRESTLER(wrestler, slot) * 4)) = 0x3C;
}

