            lift_call<s32>(ctx, n64::menu_widget_command)(1, 0x2A, 8, -0xE1E1E2, 0, 0);
            lift_call<s32>(ctx, n64::menu_widget_command)(1, 0x2A, 0x10, 0xA, 0, 0);
            lift_call<s32>(ctx, n64::make_picture_widget)(1, 0x38, 0x104, picture_x + 0x23, 0x18, 0x18, 0x4A9E, 0x4A9D, -1, -1, 0);
            command = 0x10;
