// Copies Superstar `id`'s costume `costume` record (0x4E bytes, superstar_roster_record) into edit record `edit` + 0x268 and unpacks his moveset (superstar_moveset; unpack_moveset: moves into + 0x580, its abilities from moveset + 0xB8 into + 0xC58), then reset_move_slots_from_moveset and abilities_to_move_slot_fields on the edit record. Callers select_pick_and_edit, controller_pak_page_run, reinit_rules_page. (2026-11-12, names2: confirmed from the lifted C++.)
// From the N64 function at 0x80124060 (29 instructions).
// Called by: select_pick_and_edit, controller_pak_page_run, func_80133FBC_ovl_d.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void load_superstar_into_editor(recomp_context* ctx, s32 edit, s32 id, s32 costume) {
    LiftFrame frame(ctx, 0x20);
    frame.keep(0x10, ctx->r16);
    frame.keep(0x14, ctx->r17);
    frame.keep(0x18, ctx->r31);
    LiftAbiOut lift_out_a2{ctx->r6};   // the context's a2, kept in step with the original's
    LiftAbiOut lift_out_a3{ctx->r7};   // the context's a3, kept in step with the original's
    s32 roster_record;
    s32 abilities;
    s32 abilities_out;
    s32 unused;
    s32 superstar_moveset;

    roster_record = lift_call<s32>(ctx, n64::superstar_roster_record)(id, costume);
    lift_out_a2 = 0x4E;
    lift_call<s32>(ctx, n64::copy_memory)(roster_record, edit + 0x268, 0x4E);
    superstar_moveset = lift_call<s32>(ctx, n64::superstar_moveset)(id);
    abilities = superstar_moveset + 0xB8;
    lift_out_a2 = abilities;
    abilities_out = edit + 0xC58;
    lift_out_a3 = abilities_out;
    lift_call<s32>(ctx, n64::unpack_moveset)(superstar_moveset, edit + 0x580, abilities, abilities_out);
    lift_call<s32>(ctx, n64::reset_move_slots_from_moveset)(edit);
    unused = lift_call<s32>(ctx, n64::abilities_to_move_slot_fields)(edit);
}

// Which of the eight belt labels (0x8014FD04: 0x8510-0x8517) the current screen's cursor row shows, -1 if none.
// From the N64 function at 0x801240AC (32 instructions).
// Called by: draw_superstar_row_photo, draw_superstar_row_photo_mod_copy.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 cursor_row_title_index(void) {
    s32 cursor;
    s32 rows;
    s32 menu_screen_times_312;
    s32 i;
    s32 result;
    P<u16> entry_at;
    s32 cursor_row_label;

    result = -1;
    i = 0;
    menu_screen_times_312 = GAME_VAR(menu_screen) * 0x138;
    cursor = GAME_TABLE(menu_screen_cursor, menu_screen_times_312);
    entry_at = (P<u16> )field::var::title_belt_row_labels;
    rows = GAME_TABLE(menu_screen_rows, menu_screen_times_312);
    cursor_row_label = M2C_FIELD(((cursor * 0x88) + rows), P<u16> , 0x60);
    for (;;) {
        if (cursor_row_label != *entry_at) {
            i += 1;
            entry_at += 2;
            if (i < 8) {
                continue;
            }
        } else {
            result = i;
        }
        break;
    }
    return result;
}

