// Called by: wrestler_state_5_running_collision, wrestler_state_45_hit_reaction.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 21 comparisons, no difference (leaf twin, 0.84, match_tag, menu_from_attract, rules_single_hardcore, smoke_singles).
s32 hit_reaction_file(P<void> wrestler, s32 file) {
    s32 hit_flags;
    s32 result;

    result = file;
    hit_flags = WRESTLER(wrestler, hit_flags);
    if (hit_flags & 0x02000000) {
        if (hit_flags & 0x100000) {
            result = 0x3116;
        }
        if (hit_flags & 0x200000) {
            result = 0x3118;
        }
        if (hit_flags & 0x400000) {
            result = 0x311A;
        }
        if (hit_flags & 0x800000) {
            result = 0x311C;
        }
        if (hit_flags & 0x01000000) {
            result = 0x311E;
        }
    } else {
        if (hit_flags & 0x100000) {
            result = 0x3115;
        }
        if (hit_flags & 0x200000) {
            result = 0x3117;
        }
        if (hit_flags & 0x400000) {
            result = 0x3119;
        }
        if (hit_flags & 0x800000) {
            result = 0x311B;
        }
        if (hit_flags & 0x01000000) {
            result = 0x311D;
        }
    }
    if (WRESTLER(wrestler, stamina) < 0x64) {
        result += 0xE;
    }
    return result;
}

