// In list `list` (+0 entries of 6 bytes, +6 count) the entry whose first u16 is `value`. (2026-11-12, names3: confirmed from the lifted C++: the walk over the +6 entries, 6 bytes apart, stopping at the first equal halfword (the entry is left in v0 for the caller).)
// From the N64 function at 0x801288B4 (17 instructions).
// Called by: draw_text_list_row, draw_text_list_box_row.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void find_list_entry(recomp_context* ctx, P<void> list, s32 value) {
    LiftAbiOut lift_out_a2{ctx->r6};   // the context's a2, kept in step with the original's
    LiftAbiOut lift_out_a3{ctx->r7};   // the context's a3, kept in step with the original's
    LiftAbiOut lift_out_v0{ctx->r2};   // the context's v0, kept in step with the original's
    s32 i_below_list_half_6;
    s32 i;
    P<u16> record_at;
    s32 list_half_6;
    u32 record;

    list_half_6 = M2C_FIELD(list, P<u16> , 6);
    lift_out_v0 = (s32) list_half_6;
    i = 0;
    lift_out_a2 = 0;
    if ((s32) list_half_6 > 0) {
        lift_out_a3 = (s32) list_half_6;
        record_at = M2C_FIELD(list, P<P<u16>> , 0);
        for (;;) {
            record = *record_at;
            i += 1;
            lift_out_a2 = i;
            if (record == value) {
                lift_out_v0 = (s32) record_at;
                return;
            }
            i_below_list_half_6 = i < (s32) list_half_6;
            lift_out_v0 = i_below_list_half_6;
            record_at += 6;
            if (i_below_list_half_6 == 0) {
                break;
            }
        }
    }
    lift_out_v0 = (s32) M2C_FIELD(list, P<P<u16>> , 0);
}

