    Ref<f32> sp14(frame.at(0x14));
    Ref<f32> sp18(frame.at(0x18));
    Ref<f32> sp20(frame.at(0x20));
    Ref<f32> sp24(frame.at(0x24));
    Ref<f32> sp28(frame.at(0x28));
    f32 b_z;
    f32 z;
    f32 unused;
    f32 y;
    f32 b_y;

    y = VEC3F(a, y);
    z = VEC3F(a, z);
    sp10 = VEC3F(a, x);
    sp14 = y;
    sp18 = z;
    b_y = VEC3F(b, y);
    b_z = VEC3F(b, z);
    sp20 = VEC3F(b, x);
