        lift_out_v0 = 0x64;
        lift_call<s32>(ctx, n64::menu_widget_command)(0, 0, 0x10, 0xA, 0x64, 0);
        lift_call<s32>(ctx, n64::menu_widget_command)(0, 0, 0, 0, 0, 0);
        lift_out_v0 = 1;
        lift_call<s32>(ctx, n64::menu_widget_command)(0, 8, 0, 0, -0x64, 1);
        lift_call<s32>(ctx, n64::menu_widget_command)(0, 0x37, 0, 0x8000, -0x64, 0);
        lift_call<s32>(ctx, n64::menu_widget_command)(0, 4, 0, 0, -0x64, 0);
        lift_call<s32>(ctx, n64::menu_widget_command)(0, 5, 0, 0x8000, -0x64, 0);
        lift_call<s32>(ctx, n64::menu_widget_command)(0, 6, 0, 0x8000, -0x64, 0);
        unused = lift_call<s32>(ctx, n64::menu_widget_command)(0, 7, 0, 0x8000, -0x64, 0);
        page = EDITOR_STATE_AS(editor, page, s32);
        back_page = EDITOR_PAGE(page, back_page);
        lift_out_v0 = back_page;
        GAME_VAR(pak_page_step) = 0;
