// A pair of values for the RULES page from the match type bits (0x800A957C: 0x80 with 1 / 8, 0x100 with 1 / 2 / 8, ...): 6-0xD and 8 / 9. Caller init_rules_page.
// From the N64 function at 0x80133B34 (68 instructions). The name is a best guess from the code alone.
// Called by: init_rules_page.
// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
s32 rules_page_kind(void) {
    s32 match_type;
    s32 first_value;
    s32 second_value;

    match_type = GAME_VAR(match_type);
    if (match_type & 0x80) {
        first_value = 6;
        if (match_type & 1) {
            second_value = 8;
        } else {
            second_value = 8;
            if (match_type & 8) {
                first_value = 8;
            } else {
                first_value = 7;
            }
        }
    } else if (match_type & 0x100) {
        first_value = 0xA;
        if (match_type & 1) {
            second_value = 9;
        } else {
            first_value = 0xB;
            if (match_type & 2) {
                second_value = 9;
            } else {
                second_value = 8;
                if (match_type & 8) {
                    first_value = 0xD;
                } else {
                    first_value = 0xC;
                }
            }
        }
    } else {
        first_value = 5;
        if (match_type & 0x220) {
            second_value = 8;
        } else {
            first_value = 9;
            if (!(match_type & 0x40)) {
                first_value = 0;
                if (match_type & 1) {
                    second_value = 9;
                } else {
                    first_value = 1;
                    if (match_type & 2) {
                        second_value = 9;
                    } else {
                        first_value = 3;
                        if (match_type & 8) {
                            second_value = 8;
                        } else {
                            second_value = 8;
                            if (match_type & 4) {
                                first_value = 2;
                            } else {
                                first_value = 4;
                                second_value = 2;
                            }
                        }
                    }
                }
            } else {
                second_value = 2;
            }
        }
    }
    return (first_value << 8) | second_value;
}

