    pick_offset = pick * 0xC;
    pick_record = pick_offset + field::var::select_picks;
    slot_offset = slot * 4;
    GAME_TABLE(match_slot_superstars, slot_offset) = (s32) GAME_ARRAY_AS(select_picks, pick_offset, s16);
    GAME_TABLE(match_slot_controllers, slot_offset) = (s32) M2C_FIELD(pick_record, P<u8> , 3);
    GAME_TABLE(match_slot_costumes, slot_offset) = (s32) M2C_FIELD(pick_record, P<u8> , 2);
