    GAME_TABLE(match_slot_costumes, slot_offset) = costume_low_2_bits;
    GAME_TABLE_AS(entrant_costumes, slot, s8) = (s8) costume_low_2_bits;
    GAME_TABLE(match_slot_controllers, slot_offset) = 1;
