    MENU_ROW_AT_AS(rows_3, 9, label, s16) = (s16) (GAME_VAR_AS(select_shown_page, u16) + 0x3200);
    MENU_ROW_AT(rows_3, 9, kind_data) = (u16) M2C_FIELD((((s16) MENU_SCREEN(menu_screen, cursor) * 0x88) + MENU_SCREEN(menu_screen, rows)), P<u16> , 0x62);
