// Random-tested: 200000 plain random inputs, all instructions reached, no difference. In play: 1 comparisons, no difference (leaf twin, 0.84, match_tag).
void retarget_from_paired_man(P<void> wrestler) {
    s32 other_state;
    s32 other_slot;

    other_slot = WRESTLER(wrestler, partner_slot_c);
    if (WRESTLER(wrestler, slot) != other_slot) {
        other_state = WRESTLER_IN(wrestlers, (other_slot * 0x358), state);
        switch (other_state) {
        default:
            break;
        case 0x44:
        case 0x48:
        case 0x4A:
        case 0x7F:
        case 0x81:
            WRESTLER(wrestler, target_slot) = (s32) WRESTLER_IN(wrestlers, (WRESTLER_IN(wrestlers, (WRESTLER(wrestler, partner_slot_c) * 0x358), target_slot) * 0x358), partner_slot_c);
            return;
        case 0x45:
        case 0x49:
        case 0x4B:
        case 0x80:
        case 0x82:
            WRESTLER(wrestler, target_slot) = (s32) WRESTLER_IN(wrestlers, (WRESTLER(wrestler, partner_slot_c) * 0x358), target_slot);
            break;
        }
    }
}

