            VERTEX_VIA_AT_AS(record_at, a, -3, g, s8) = 0xFF;
            VERTEX_VIA_AT_AS(record_at, a, -3, b, s8) = 0xFF;
            VERTEX_VIA_AT_AS(record_at, a, -3, a, s8) = 0;
            VERTEX_VIA_AT(record_at, a, -2, y) = strip_top;
            VERTEX_VIA_AT(record_at, a, -2, z) = 0;
            VERTEX_VIA_AT_AS(record_at, a, -2, flag, s16) = 0;
