            VERTEX_VIA_AT_AS(record_at, a, -2, r, s8) = 0xFF;
            VERTEX_VIA_AT_AS(record_at, a, -2, g, s8) = 0xFF;
            VERTEX_VIA_AT_AS(record_at, a, -2, b, s8) = 0xFF;
            VERTEX_VIA_AT_AS(record_at, a, -2, a, s8) = 0;
