            VERTEX_VIA(record_at, a, z) = 0;
            VERTEX_VIA_AS(record_at, a, flag, s16) = 0;
            VERTEX_VIA(record_at, a, s) = 0x2800;
            VERTEX_VIA(record_at, a, t) = 0x180;
            VERTEX_VIA_AS(record_at, a, r, s8) = 0xFF;
            VERTEX_VIA_AS(record_at, a, g, s8) = 0xFF;
            VERTEX_VIA_AS(record_at, a, b, s8) = 0xFF;
            VERTEX_VIA_AS(record_at, a, a, s8) = 0;
            record_at += 0x40;
            M2C_FIELD(gfx_at, P<s32> , -4) = 0xFD500000;
            picture = WIDGET_AS(widget_2, picture, s32);
            vertex_2 += 0x40;
