            strip = next_strip;
            pixels_offset_now = pixels_offset;
            M2C_FIELD(command_at, P<s32> , 8) = (s32) ((picture + pixels_offset_now) - field::var::kseg0);
            gfx_at_2 = gfx_at + 8;
            M2C_FIELD(gfx_at_2, P<s32> , -4) = 0xF5500000;
            M2C_FIELD(gfx_at, P<s32> , 8) = 0x07080200;
            gfx_at_3 = gfx_at_2 + 8;
            M2C_FIELD(gfx_at_3, P<s32> , -4) = 0xE6000000;
            M2C_FIELD(gfx_at_2, P<s32> , 8) = 0;
