            M2C_FIELD(gfx_at_3, P<s32> , 8) = 0x073BF067;
            gfx_at_5 = gfx_at_4 + 8;
            M2C_FIELD(gfx_at_5, P<s32> , -4) = 0xE7000000;
            M2C_FIELD(gfx_at_4, P<s32> , 8) = 0;
            gfx_at_6 = gfx_at_5 + 8;
            M2C_FIELD(gfx_at_6, P<s32> , -4) = 0xF5402800;
            M2C_FIELD(gfx_at_5, P<s32> , 8) = 0x80200;
            gfx_at_7 = gfx_at_6 + 8;
            M2C_FIELD(gfx_at_7, P<s32> , -4) = 0xF2000000;
            M2C_FIELD(gfx_at_6, P<s32> , 8) = 0x4FC02C;
            gfx_at_8 = gfx_at_7 + 8;
