// Random-tested: 200000 plain random inputs, all instructions reached, no difference.
void keyboard_key_place(P<void> row) {
    s32 list_top;
    s32 label_low_byte;
    s32 place_value;
    s32 label;

    label = MENU_ROW(row, label);
    if (label & 0x80) {
        GAME_VAR(keyboard_grid_column) = 0xF;
        place_value = 0x10D;
        GAME_VAR(keyboard_grid_row) = place_value;
        return;
    }
    label_low_byte = label & 0xFF;
    switch (label_low_byte) {
    case 0x40:
        GAME_VAR(keyboard_grid_column) = 5;
        place_value = 0x14;
        GAME_VAR(keyboard_grid_row) = place_value;
        return;
    case 0x44:
        GAME_VAR(keyboard_grid_column) = 6;
        place_value = 2;
        GAME_VAR(keyboard_grid_row) = place_value;
        return;
    case 0x45:
        GAME_VAR(keyboard_grid_column) = 7;
        list_top = MENU_ROW(row, list_top);
        GAME_VAR(keyboard_grid_row) = (s32) (list_top + 6) / 7;
        return;
    case 0x48:
        place_value = 6;
        GAME_VAR(keyboard_grid_column) = 6;
        GAME_VAR(keyboard_grid_row) = place_value;
        return;
    case 0x49:
        GAME_VAR(keyboard_grid_column) = 3;
        place_value = 5;
        GAME_VAR(keyboard_grid_row) = place_value;
        return;
    default:
        GAME_VAR(keyboard_grid_column) = 0xF;
        place_value = 6;
        GAME_VAR(keyboard_grid_row) = place_value;
        return;
    }
}

