void step_widget_glide(P<void> widget) {
    f32 step_y;
    f32 target_x;
    f32 target_y;
    f32 step_x_magnitude;
    f32 distance_y;
    f32 distance_x;
    s32 effects;

    target_x = WIDGET(widget, target_x);
    WIDGET(widget, x) = (f32) (WIDGET(widget, x) + WIDGET(widget, step_x));
    distance_x = target_x - WIDGET(widget, x);
    WIDGET(widget, y) = (f32) (WIDGET(widget, y) + WIDGET(widget, step_y));
    if (distance_x < 0.0f) {
        distance_x = -distance_x;
    }
    step_x_magnitude = WIDGET(widget, step_x);
    if (step_x_magnitude < 0.0f) {
        step_x_magnitude = -step_x_magnitude;
    }
    if (!(distance_x < step_x_magnitude)) {
        distance_y = WIDGET(widget, target_y) - WIDGET(widget, y);
        if (distance_y < 0.0f) {
            distance_y = -distance_y;
        }
        step_y = WIDGET(widget, step_y);
        if (step_y < 0.0f) {
            if (distance_y < -step_y) {
                goto block_11;
            }
        } else if (distance_y < step_y) {
            goto block_11;
        }
    } else {
block_11:
        effects = WIDGET(widget, effects);
        target_y = WIDGET(widget, target_y);
        WIDGET(widget, x) = (f32) WIDGET(widget, target_x);
        WIDGET(widget, y) = target_y;
        WIDGET(widget, effects) = (s32) (effects & ~1);
    }
}

